const COIN_VALUES = {
  nickel: 5,
  dime: 10,
  quarter: 25,
};

const PRODUCT_PRICES = {
  cola: 75,
  chips: 50,
  candy: 65,
};

function coinValue(action) {
  if (action === 'nickel') {
    return COIN_VALUES.nickel;
  }
  if (action === 'dime') {
    return COIN_VALUES.dime;
  }
  if (action === 'quarter') {
    return COIN_VALUES.quarter;
  }
  return 0;
}

function formatCents(cents) {
  const dollars = Math.floor(cents / 100);
  const remainder = cents % 100;
  return '$' + dollars + '.' + (remainder < 10 ? '0' + remainder : String(remainder));
}

function vend(actions) {
  const log = [];
  let balance = 0;

  for (const action of actions) {
    const value = coinValue(action);
    if (value !== 0) {
      balance += value;
      continue;
    }

    if (action === 'refund') {
      if (balance > 0) {
        log.push('Refunded ' + formatCents(balance));
        balance = 0;
      }
      continue;
    }

    const price = PRODUCT_PRICES[action];
    if (price === undefined) {
      log.push('Unknown action: ' + action);
    } else if (balance >= price) {
      balance -= price;
      log.push('Dispensed ' + action + ' for ' + formatCents(price));
    } else {
      log.push('Insufficient funds for ' + action + ': need ' + formatCents(price - balance) + ' more');
    }
  }

  return log;
}

function report(actions) {
  const log = vend(actions);
  if (log.length === 0) {
    return 'No transactions recorded.';
  }
  return log.map((line, index) => index + 1 + '. ' + line).join('\n');
}

console.log(report(['quarter', 'quarter', 'quarter', 'cola', 'refund']));
console.log(report(['dime', 'chips', 'quarter', 'quarter', 'nickel', 'dime', 'chips', 'refund']));
console.log(report(['quarter', 'slug', 'candy', 'quarter', 'quarter', 'dime', 'candy', 'refund']));

