'use strict';

const ESCAPES = { '&': '&amp;', '<': '&lt;', '>': '&gt;' };

function escapeHtml(value) {
  return value.replace(/[&<>]/g, function (ch) {
    return ESCAPES[ch];
  });
}

function isBullet(ch) {
  if (ch === '-') {
    return true;
  }
  return ch === '*';
}

function headingLevel(trimmed) {
  let level = 0;
  while (level < trimmed.length && trimmed.charAt(level) === '#') {
    level += 1;
  }
  return level > 6 ? 6 : level;
}

function stripMarker(trimmed, markerLength) {
  return trimmed.slice(markerLength).trim();
}

function convert(text) {
  const lines = String(text).split('\n');
  const out = [];
  let state = 'none';

  for (const line of lines) {
    const trimmed = line.trim();

    if (trimmed === '') {
      if (state === 'ul') {
        out.push('</ul>');
      }
      state = 'none';
      continue;
    }

    const marker = trimmed.charAt(0);

    if (isBullet(marker)) {
      if (state !== 'ul') {
        out.push('<ul>');
        state = 'ul';
      }
      out.push('<li>' + escapeHtml(stripMarker(trimmed, 1)) + '</li>');
    } else if (marker === '#') {
      if (state === 'ul') {
        out.push('</ul>');
      }
      const level = headingLevel(trimmed);
      const body = escapeHtml(stripMarker(trimmed, level));
      out.push('<h' + level + '>' + body + '</h' + level + '>');
      state = 'heading';
    } else {
      if (state === 'ul') {
        out.push('</ul>');
      }
      out.push('<p>' + escapeHtml(trimmed) + '</p>');
      state = 'paragraph';
    }
  }

  if (state === 'ul') {
    out.push('</ul>');
  }
  return out.join('\n');
}

function main() {
  const fs = require('fs');
  const input = fs.readFileSync(0, 'utf8');
  const html = convert(input);
  if (html !== '') {
    process.stdout.write(html + '\n');
  }
}

if (require.main === module) {
  main();
}

module.exports = { convert, escapeHtml, headingLevel };

