const STRUCTURAL = ['{', '}', '[', ']', ':', ','];

function isStructural(ch) {
  for (let i = 0; i < STRUCTURAL.length; i += 1) {
    if (STRUCTURAL[i] === ch) {
      return true;
    }
  }
  return false;
}

function isWhitespace(ch) {
  if (ch === ' ') {
    return true;
  }
  if (ch === '\t') {
    return true;
  }
  if (ch === '\r') {
    return true;
  }
  return ch === '\n';
}

function readString(text, start) {
  let i = start + 1;
  let raw = '"';
  while (i < text.length) {
    const ch = text[i];
    if (ch === '\\') {
      raw += ch + (text[i + 1] || '');
      i += 2;
      continue;
    }
    raw += ch;
    i += 1;
    if (ch === '"') {
      return { token: raw, next: i };
    }
  }
  throw new Error('unterminated string starting at index ' + start);
}

function readLiteral(text, start) {
  let i = start;
  while (i < text.length) {
    const ch = text[i];
    if (isWhitespace(ch) || isStructural(ch) || ch === '"') {
      break;
    }
    i += 1;
  }
  return { token: text.slice(start, i), next: i };
}

function tokenize(text) {
  if (typeof text !== 'string') {
    throw new TypeError('tokenize expects a string');
  }
  const tokens = [];
  let i = 0;
  while (i < text.length) {
    const ch = text[i];
    if (isWhitespace(ch)) {
      i += 1;
    } else if (isStructural(ch)) {
      tokens.push(ch);
      i += 1;
    } else if (ch === '"') {
      const scanned = readString(text, i);
      tokens.push(scanned.token);
      i = scanned.next;
    } else {
      const scanned = readLiteral(text, i);
      tokens.push(scanned.token);
      i = scanned.next;
    }
  }
  return tokens;
}

function describe(token) {
  if (token.length === 1 && isStructural(token)) {
    return 'punct';
  }
  if (token[0] === '"') {
    return 'string';
  }
  return 'literal';
}

function report(text) {
  const tokens = tokenize(text);
  const lines = tokens.map((t, n) => n + ': ' + describe(t) + ' ' + t);
  return lines.join('\n');
}

const sample = '{ "name": "ada", "tags": ["math", "code"], "active": true }';
console.log(report(sample));
console.log('token count: ' + tokenize(sample).length);

module.exports = { tokenize, report, describe };

