const ENTITIES = {
  lt: '<',
  gt: '>',
  amp: '&',
  quot: '"',
  apos: "'",
  nbsp: '\u00A0',
  copy: '\u00A9'
};

function resolveEntity(name) {
  if (name.length === 0) {
    return null;
  }
  const symbol = ENTITIES[name];
  if (symbol === undefined) {
    return null;
  }
  return symbol;
}

function findEntityEnd(text, ampIndex) {
  for (let i = ampIndex + 1; i < text.length; i++) {
    if (text.charAt(i) === ';') {
      return i;
    }
  }
  return -1;
}

function decode(text) {
  if (typeof text !== 'string') {
    throw new TypeError('decode expects a string');
  }
  let out = '';
  let i = 0;
  while (i < text.length) {
    const ch = text.charAt(i);
    if (ch !== '&') {
      out += ch;
      i += 1;
      continue;
    }
    const end = findEntityEnd(text, i);
    if (end === -1) {
      out += text.slice(i);
      break;
    }
    const word = text.slice(i + 1, end);
    const symbol = resolveEntity(word);
    out += symbol === null ? '&' + word : symbol;
    i = end + 1;
  }
  return out;
}

function escapeVisible(text) {
  let shown = '';
  for (const ch of text) {
    if (ch.codePointAt(0) === 0x00A0) {
      shown += '<nbsp>';
    } else if (ch === '\n') {
      shown += '\\n';
    } else {
      shown += ch;
    }
  }
  return shown;
}

function describeChange(original, decoded) {
  if (decoded === original) {
    return 'no entities replaced';
  }
  return 'shortened by ' + (original.length - decoded.length) + ' char(s)';
}

