function assertLines(lines) {
  if (!Array.isArray(lines)) {
    throw new TypeError('parselog expects an array of log lines');
  }
  for (const line of lines) {
    if (typeof line !== 'string') {
      throw new TypeError('every log line must be a string');
    }
  }
}

function parselog(lines) {
  assertLines(lines);
  let state = 'disconnected';
  let requests = 0;
  let errors = 0;

  for (const line of lines) {
    if (line === 'disconnect') {
      state = 'disconnected';
      continue;
    }
    switch (state) {
      case 'disconnected':
        if (line === 'connect') {
          state = 'connected';
        } else {
          errors += 1;
        }
        break;
      case 'connected':
        if (line === 'authenticate') {
          state = 'authenticated';
        } else {
          errors += 1;
        }
        break;
      default:
        if (line === 'request') {
          requests += 1;
        } else {
          errors += 1;
        }
        break;
    }
  }

  return [state, requests, errors];
}

function formatReport(result) {
  const [state, requests, errors] = result;
  const requestWord = requests === 1 ? 'request' : 'requests';
  const errorWord = errors === 1 ? 'error' : 'errors';
  const health = errors === 0 ? 'clean run' : 'protocol violations found';
  const tail = state !== 'disconnected' ? 'session still open' : 'session closed';
  return `${state}: ${requests} ${requestWord}, ${errors} ${errorWord} — ${health}, ${tail}`;
}

function main() {
  const sessions = [
    ['connect', 'authenticate', 'request', 'request', 'disconnect'],
    ['connect', 'request', 'authenticate', 'request'],
    ['authenticate', 'disconnect', 'connect', 'connect'],
    []
  ];

  for (const session of sessions) {
    const result = parselog(session);
    const label = session.length === 0 ? '(empty log)' : session.join(' -> ');
    console.log(label);
    console.log('  ' + JSON.stringify(result));
    console.log('  ' + formatReport(result));
  }
}

main();

