const FILES = 'abcdefgh';

function parseSquare(square) {
  if (typeof square !== 'string') return null;
  if (square.length !== 2) return null;
  const file = FILES.indexOf(square[0]);
  if (file === -1) return null;
  const rank = Number(square[1]);
  if (Number.isInteger(rank) !== true) return null;
  if (rank < 1 || rank > 8) return null;
  return { file, rank };
}

function rankStepIsLegal(color, fromRank, toRank) {
  const delta = toRank - fromRank;
  if (color === 'white') {
    if (delta === 1) return true;
    if (fromRank !== 2) return false;
    return delta === 2;
  }
  if (color === 'black') {
    if (delta === -1) return true;
    if (fromRank !== 7) return false;
    return delta === -2;
  }
  return false;
}

function fileStepIsLegal(capture, fromFile, toFile) {
  const steps = Math.abs(toFile - fromFile);
  if (capture === true) {
    return steps === 1;
  }
  return steps === 0;
}

function validate(move) {
  if (Array.isArray(move) !== true) return false;
  if (move.length !== 4) return false;
  const [start, end, color, capture] = move;
  if (typeof capture !== 'boolean') return false;
  const from = parseSquare(start);
  if (from === null) return false;
  const to = parseSquare(end);
  if (to === null) return false;
  if (rankStepIsLegal(color, from.rank, to.rank) !== true) return false;
  if (capture === true) {
    if (Math.abs(to.rank - from.rank) !== 1) return false;
  }
  return fileStepIsLegal(capture, from.file, to.file);
}

function describe(move) {
  const [start, end, color, capture] = move;
  const action = capture === true ? 'captures on' : 'advances to';
  return `${color} pawn on ${start} ${action} ${end}`;
}

function report(moves) {
  return moves.map((move) => {
    const verdict = validate(move) === true ? 'legal' : 'illegal';
    return `${describe(move)}: ${verdict}`;
  });
}

const requests = [
  ['a2', 'a3', 'white', false],
  ['a2', 'a4', 'white', false],
  ['a3', 'a5', 'white', false],
  ['b4', 'c5', 'white', true],
  ['b4', 'b5', 'white', true],
  ['e7', 'e5', 'black', false],
  ['e6', 'd5', 'black', true],
  ['e6', 'e7', 'black', false],
  ['h8', 'h9', 'white', false],
];

for (const line of report(requests)) {
  console.log(line);
}

