const VALID_COMMANDS = ['up', 'down', 'open', 'close', 'alarm', 'reset'];

function isValidCommand(command) {
  if (typeof command !== 'string') {
    return false;
  }
  return VALID_COMMANDS.some(function (name) {
    return name === command;
  });
}

function validate(commands) {
  if (Array.isArray(commands) !== true) {
    throw new TypeError('commands must be an array of strings');
  }
  const bad = [];
  for (let i = 0; i < commands.length; i += 1) {
    if (isValidCommand(commands[i]) === false) {
      bad.push(i);
    }
  }
  if (bad.length !== 0) {
    throw new Error('unknown command at index ' + bad.join(', '));
  }
  return commands;
}

function simulate(commands) {
  validate(commands);
  let floor = 0;
  let state = 'closed';
  const history = [];
  for (const command of commands) {
    switch (command) {
      case 'up':
        if (state === 'closed') {
          floor += 1;
          history.push(floor);
        }
        break;
      case 'down':
        if (state === 'closed') {
          floor -= 1;
          history.push(floor);
        }
        break;
      case 'open':
        if (floor >= 0) {
          state = 'open';
        }
        break;
      case 'close':
        if (floor >= 0) {
          state = 'closed';
        }
        break;
      case 'alarm':
        if (state === 'closed') {
          state = 'emergency';
        }
        break;
      case 'reset':
        if (state === 'emergency') {
          state = 'closed';
        }
        break;
    }
  }
  return history;
}

function report(commands) {
  const history = simulate(commands);
  if (history.length === 0) {
    return 'no movement';
  }
  const final = history[history.length - 1];
  let direction = 'ground';
  if (final > 0) {
    direction = 'above';
  } else if (final < 0) {
    direction = 'below';
  }
  return history.join(' -> ') + ' (ended ' + direction + ')';
}

