function normalizeRank(card) {
  if (typeof card !== 'string') {
    throw new TypeError(`card rank must be a string, received ${typeof card}`);
  }
  return card.trim().toLowerCase();
}

function isFaceCard(rank) {
  if (rank === 'jack') {
    return true;
  }
  if (rank === 'queen') {
    return true;
  }
  return rank === 'king';
}

function parseNumericRank(rank) {
  if (!/^-?\d+$/.test(rank)) {
    return null;
  }
  return parseInt(rank, 10);
}

function evaluate(cards) {
  let score = 0;
  let aces = 0;

  for (const card of cards) {
    const rank = normalizeRank(card);

    if (isFaceCard(rank)) {
      score += 10;
      continue;
    }
    if (rank === 'ace') {
      score += 11;
      aces += 1;
      continue;
    }
    if (rank === 'joker') {
      if (score === 0) {
        score += 15;
      }
      continue;
    }

    const value = parseNumericRank(rank);
    if (value !== null) {
      score += value;
    }
  }

  while (score > 21 && aces > 0) {
    score -= 10;
    aces -= 1;
  }

  if (score === 21) {
    return 'blackjack';
  }
  if (score === 22) {
    return 'bust';
  }
  if (score > 22) {
    return 'bust';
  }
  return score;
}

function describeOutcome(result) {
  if (result === 'blackjack') {
    return 'blackjack (exactly 21)';
  }
  if (result === 'bust') {
    return 'bust (over 21)';
  }
  return `score ${result}`;
}

function report(hands) {
  let busted = 0;
  const lines = hands.map((hand) => {
    const outcome = evaluate(hand);
    if (outcome === 'bust') {
      busted += 1;
    }
    return `${hand.join(' + ')} -> ${describeOutcome(outcome)}`;
  });
  lines.push(`${busted} of ${hands.length} hand(s) busted`);
  return lines;
}

const sampleHands = [
  ['ace', 'king'],
  ['joker', '6'],
  ['ace', 'ace', '9'],
  ['queen', 'jack', '5'],
  ['7', '7', '8'],
];

for (const line of report(sampleHands)) {
  console.log(line);
}

module.exports = { evaluate, describeOutcome, report };

