'use strict';

const KNOWN_CONDITIONS = ['rain', 'sun', 'frost', 'drought', 'fertilizer', 'bugs'];

function normalizeCondition(condition) {
  if (typeof condition !== 'string') {
    throw new TypeError('each condition must be a string');
  }
  const cleaned = condition.trim().toLowerCase();
  if (cleaned === '') {
    throw new RangeError('conditions must not be blank');
  }
  return cleaned;
}

function isKnownCondition(condition) {
  return KNOWN_CONDITIONS.indexOf(condition) !== -1;
}

function grow(conditions) {
  if (!Array.isArray(conditions)) {
    throw new TypeError('conditions must be an array');
  }
  let state = 'seed';
  let health = 5;
  for (const raw of conditions) {
    const condition = normalizeCondition(raw);
    if (state === 'dead') {
      if (condition === 'rain') {
        continue;
      }
    }
    if (state === 'seed') {
      if (condition === 'rain') {
        state = 'sprout';
      }
    } else if (state === 'sprout') {
      if (condition === 'sun') {
        state = 'leaf';
      }
    } else if (state === 'leaf') {
      if (condition === 'frost') {
        health -= 2;
      }
    }
    if (health === 0) {
      if (condition === 'drought') {
        state = 'dead';
      }
    }
    if (condition === 'fertilizer') {
      if (state === 'leaf') {
        health += 3;
      }
    } else if (condition === 'bugs') {
      if (state === 'sprout') {
        health -= 1;
      }
    }
  }
  return [state, health];
}

function describe(conditions) {
  const unknown = conditions
    .map(normalizeCondition)
    .filter((condition) => !isKnownCondition(condition));
  const [state, health] = grow(conditions);
  const note = unknown.length === 0 ? 'all conditions recognized' : `unrecognized: ${unknown.join(', ')}`;
  const vitality = state === 'dead' ? 'no vitality' : `health ${health}`;
  return `${conditions.length} step(s) -> ${state} (${vitality}); ${note}`;
}

function main() {
  const trials = [
    ['rain', 'sun', 'fertilizer'],
    ['rain', 'bugs', 'bugs', 'sun', 'frost', 'frost', 'frost', 'drought', 'rain'],
    ['hail', 'rain', 'sun', 'frost'],
    []
  ];
  for (const trial of trials) {
    console.log(describe(trial));
  }
}

main();

module.exports = { grow, describe, normalizeCondition, isKnownCondition };

