function validateTriggers(triggers) {
  if (Array.isArray(triggers) !== true) {
    throw new TypeError('triggers must be an array of event strings');
  }
  return triggers.filter(function (trigger) {
    return typeof trigger === 'string';
  });
}

function execute(triggers) {
  var lights = 'off';
  var blinds = 'off';
  var alarm = 'off';
  var events = validateTriggers(triggers);

  for (var i = 0; i < events.length; i += 1) {
    var trigger = events[i];
    if (trigger === 'sunrise') {
      if (alarm === 'off') {
        lights = 'off';
        blinds = 'open';
      }
    } else if (trigger === 'sunset') {
      if (alarm === 'off') {
        lights = 'on';
        blinds = 'closed';
      }
    } else if (trigger === 'motion') {
      if (alarm === 'on') {
        return ['police', lights, blinds, alarm];
      }
    } else if (trigger === 'arm') {
      if (lights === 'off') {
        alarm = 'on';
      }
    } else if (trigger === 'disarm') {
      if (alarm === 'on') {
        alarm = 'off';
      }
    } else if (trigger === 'smoke') {
      if (blinds === 'closed') {
        blinds = 'open';
      }
    }
  }

  return [lights, blinds, alarm];
}

function describe(states) {
  var alerted = states[0] === 'police';
  var offset = alerted ? 1 : 0;
  var labels = ['lights', 'blinds', 'alarm'];
  var parts = labels.map(function (label, index) {
    return label + '=' + states[index + offset];
  });
  if (alerted) {
    parts.unshift('POLICE CALLED');
  }
  return parts.join(', ');
}

function report(scenarios) {
  var lines = [];
  Object.keys(scenarios).forEach(function (name) {
    var states = execute(scenarios[name]);
    var flag = states[0] === 'police' ? '!' : ' ';
    lines.push(flag + ' ' + name + ': ' + describe(states));
  });
  return lines.join('\n');
}

var scenarios = {
  quiet_night: ['sunset', 'sunrise'],
  armed_away: ['sunrise', 'arm', 'motion'],
  fire_drill: ['sunset', 'smoke', 'arm', 'disarm'],
  ignored: ['sunset', 'arm', 'sunrise']
};

console.log(report(scenarios));

module.exports = { execute: execute, describe: describe, report: report };

