const KNOWN_ITEMS = ['burger', 'fries', 'soda', 'combo', 'cancel', 'employee', 'manager'];

function normalizeItem(raw) {
  if (typeof raw !== 'string') {
    return null;
  }
  const trimmed = raw.trim().toLowerCase();
  if (trimmed === '') {
    return null;
  }
  return trimmed;
}

function ring(orders) {
  if (!Array.isArray(orders)) {
    throw new TypeError('orders must be an array of menu items');
  }
  let subtotal = 0;
  for (const raw of orders) {
    const item = normalizeItem(raw);
    if (item === null) {
      continue;
    }
    if (item === 'burger') {
      if (subtotal === 0) {
        subtotal += 5;
      }
    } else if (item === 'fries') {
      if (subtotal > 0) {
        subtotal += 2;
      }
    } else if (item === 'soda') {
      if (subtotal > 0) {
        subtotal += 1;
      }
    } else if (item === 'combo') {
      if (subtotal === 0) {
        subtotal += 7;
      }
    } else if (item === 'cancel') {
      if (subtotal > 0) {
        subtotal = 0;
      }
    } else if (item === 'employee') {
      if (subtotal > 0) {
        subtotal *= 0.5;
      }
    } else if (item === 'manager') {
      if (subtotal === 0) {
        console.log('Good day, manager!');
      }
    }
  }
  return subtotal;
}

function formatMoney(amount) {
  const cents = Math.round(amount * 100);
  const remainder = cents % 100;
  return '$' + Math.floor(cents / 100) + '.' + String(remainder).padStart(2, '0');
}

function unknownItems(orders) {
  const found = [];
  for (const raw of orders) {
    const item = normalizeItem(raw);
    if (item !== null && !KNOWN_ITEMS.includes(item)) {
      found.push(item);
    }
  }
  return found;
}

function report(label, orders) {
  const total = ring(orders);
  const status = total === 0 ? 'no charge' : 'amount due';
  console.log(label + ': ' + formatMoney(total) + ' (' + status + ')');
  const strays = unknownItems(orders);
  if (strays.length !== 0) {
    console.log('  ignored items: ' + strays.join(', '));
  }
  return total;
}

const walkIn = report('walk-in', ['burger', 'fries', 'soda']);
const staff = report('staff meal', ['burger', 'fries', 'soda', 'employee']);
if (staff !== walkIn) {
  console.log('Staff discount saved ' + formatMoney(walkIn - staff));
}
report('voided ticket', ['combo', 'soda', 'cancel']);
report('opening shift', ['manager', 'fries', 'combo', 'nachos']);

