function validateIngredients(ingredients) {
  if (!Array.isArray(ingredients)) {
    throw new TypeError('ingredients must be an array');
  }
  for (const item of ingredients) {
    if (typeof item !== 'string') {
      throw new TypeError('every ingredient must be a string');
    }
  }
  return ingredients;
}

function brew(ingredients) {
  validateIngredients(ingredients);
  let toxicity = 0;
  let magicPower = 0;

  for (const ingredient of ingredients) {
    if (ingredient === 'toadstool') {
      if (toxicity === 0) {
        toxicity += 2;
      }
    } else if (ingredient === 'nightshade') {
      if (toxicity > 0) {
        toxicity += 3;
      }
    } else if (ingredient === 'moonstone') {
      if (magicPower === 0) {
        magicPower += 5;
      }
    } else if (ingredient === 'unicornhair') {
      if (toxicity > 0) {
        toxicity = 0;
        magicPower *= 2;
      }
    } else if (ingredient === 'dragonscale') {
      if (magicPower === 0) {
        toxicity = 10;
      }
    } else if (ingredient === 'bezoar') {
      if (toxicity === 10) {
        toxicity -= 10;
      }
    }
  }

  return [toxicity, magicPower];
}

function classify(toxicity, magicPower) {
  if (toxicity === 0 && magicPower > 0) {
    return 'elixir';
  }
  if (magicPower === 0 && toxicity > 0) {
    return 'poison';
  }
  if (toxicity > 0) {
    return 'unstable mixture';
  }
  return 'plain water';
}

function formatRecipe(ingredients) {
  return ingredients.length === 0 ? '(nothing)' : ingredients.join(' + ');
}

function describe(ingredients) {
  const [toxicity, magicPower] = brew(ingredients);
  return `${formatRecipe(ingredients)} -> toxicity ${toxicity}, magic ${magicPower} (${classify(toxicity, magicPower)})`;
}

function main() {
  const recipes = [
    [],
    ['toadstool', 'nightshade', 'unicornhair'],
    ['moonstone', 'toadstool', 'nightshade', 'unicornhair'],
    ['dragonscale', 'bezoar', 'moonstone'],
    ['moonstone', 'dragonscale', 'bezoar'],
    ['toadstool', 'toadstool', 'bezoar', 'moonstone', 'moonstone']
  ];

  for (const recipe of recipes) {
    console.log(describe(recipe));
  }

  const strongest = recipes.reduce((best, recipe) => {
    return brew(recipe)[1] > brew(best)[1] ? recipe : best;
  }, recipes[0]);
  console.log(`strongest brew: ${formatRecipe(strongest)}`);
}

main();

