const UNIT_ALIASES = {
  cups: 'cup',
  c: 'cup',
  tablespoons: 'tablespoon',
  tbsp: 'tablespoon',
  teaspoons: 'teaspoon',
  tsp: 'teaspoon',
  ounces: 'ounce',
  oz: 'ounce',
  grams: 'gram',
  g: 'gram'
};

const CONVERSIONS = [
  { unit: 'cup', item: 'flour', grams: 120 },
  { unit: 'cup', item: 'sugar', grams: 200 },
  { unit: 'tablespoon', item: 'butter', grams: 15 },
  { unit: 'teaspoon', item: 'salt', grams: 6 },
  { unit: 'ounce', item: 'chocolate', grams: 28 }
];

function normalizeUnit(unit) {
  const clean = String(unit).trim().toLowerCase();
  const alias = UNIT_ALIASES[clean];
  if (alias === undefined) {
    return clean;
  }
  return alias;
}

function normalizeItem(item) {
  return String(item).trim().toLowerCase();
}

function findRule(unit, item) {
  for (const rule of CONVERSIONS) {
    if (rule.unit !== unit) {
      continue;
    }
    if (rule.item === item) {
      return rule;
    }
  }
  return null;
}

function gramsFor(record) {
  const unit = normalizeUnit(record.unit);
  const item = normalizeItem(record.item);
  const quantity = Number(record.quantity);
  if (Number.isNaN(quantity)) {
    throw new TypeError('quantity must be numeric for ' + item);
  }
  if (unit === 'gram') {
    return quantity;
  }
  const rule = findRule(unit, item);
  if (rule === null) {
    throw new Error('no conversion for ' + quantity + ' ' + unit + ' of ' + item);
  }
  return quantity * rule.grams;
}

function convert(ingredients) {
  if (!Array.isArray(ingredients)) {
    throw new TypeError('ingredients must be an array');
  }
  let total = 0;
  for (const record of ingredients) {
    total += gramsFor(record);
  }
  return total;
}

function report(ingredients) {
  const lines = ingredients.map(function (record) {
    const unit = normalizeUnit(record.unit);
    const plural = Number(record.quantity) === 1 ? '' : 's';
    return record.quantity + ' ' + unit + plural + ' ' + normalizeItem(record.item) +
      ' -> ' + gramsFor(record) + ' g';
  });
  lines.push('total: ' + convert(ingredients) + ' g');
  return lines.join('\n');
}

