  { name: 'vanilla', size: 'single' },
  { name: 'Vanilla', size: 'double' },
  { name: 'chocolate', size: 'single' },
  { name: 'sprinkles', size: 'regular' },
  { name: 'fudge', size: 'extra' }
];

console.log(describe([{ name: 'vanilla', size: 'single' }, { name: 'sprinkles', size: 'regular' }]));
console.log('');
console.log(describe(order));

