const SOIL_LEVELS = ['light', 'normal', 'heavy'];

function isMaterial(record, material) {
  return record.material === material;
}

function isColor(record, color) {
  return record.color === color;
}

function isSoil(record, soil) {
  return record.soil === soil;
}

function normalizeRecord(record) {
  if (record === null) {
    throw new TypeError('A laundry record cannot be null');
  }
  if (typeof record !== 'object') {
    throw new TypeError('Each laundry record must be an object');
  }
  const material = String(record.material || '').trim().toLowerCase();
  const color = String(record.color || '').trim().toLowerCase();
  const soil = String(record.soil || '').trim().toLowerCase();
  if (material === '') {
    throw new Error('Record is missing a material');
  }
  if (SOIL_LEVELS.indexOf(soil) === -1) {
    throw new Error('Unknown soil level: ' + record.soil);
  }
  return { material: material, color: color, soil: soil };
}

function selectCycle(record) {
  const r = normalizeRecord(record);
  if (isMaterial(r, 'silk') && isSoil(r, 'light')) {
    return 'delicate';
  }
  if (isMaterial(r, 'wool') && isColor(r, 'dark')) {
    return 'cold wash';
  }
  if (isColor(r, 'white') && isSoil(r, 'heavy')) {
    return 'bleach';
  }
  if (isMaterial(r, 'cotton') && isSoil(r, 'heavy')) {
    return 'heavy duty';
  }
  if (isMaterial(r, 'synthetic') && isColor(r, 'mixed')) {
    return 'color catcher';
  }
  return 'normal';
}

function optimize(loads) {
  if (!Array.isArray(loads)) {
    throw new TypeError('optimize expects an array of laundry records');
  }
  return loads.map(selectCycle);
}

function summarize(cycles) {
  const counts = new Map();
  for (const cycle of cycles) {
    const seen = counts.get(cycle);
    counts.set(cycle, seen === undefined ? 1 : seen + 1);
  }
  return counts;
}

function formatReport(loads, cycles) {
  const lines = [];
  for (let i = 0; i < loads.length; i += 1) {
    const load = loads[i];
    const label = load.color === undefined ? load.material : load.material + '/' + load.color;
    lines.push(`${i + 1}. ${label} (${load.soil} soil) -> ${cycles[i]}`);
  }
  for (const [cycle, count] of summarize(cycles)) {
    const noun = count === 1 ? 'load' : 'loads';
    lines.push(`   ${cycle}: ${count} ${noun}`);
  }
  return lines.join('\n');
}

const basket = [
  { material: 'Silk', color: 'pastel', soil: 'light' },
  { material: 'wool', color: 'dark', soil: 'normal' },
  { material: 'linen', color: 'white', soil: 'heavy' },
  { material: 'cotton', color: 'dark', soil: 'heavy' },
  { material: 'synthetic', color: 'mixed', soil: 'normal' },
  { material: 'denim', color: 'dark', soil: 'light' }
];

console.log(formatReport(basket, optimize(basket)));

