const VALID_COLUMNS = ['backlog', 'progress', 'testing', 'done', 'archived'];
const VALID_ACTIONS = ['start', 'review', 'approve', 'reject', 'archive'];

function validateTicket(ticket, index) {
  if (ticket === null) {
    throw new TypeError('ticket at index ' + index + ' must be an object');
  }
  if (typeof ticket !== 'object') {
    throw new TypeError('ticket at index ' + index + ' must be an object');
  }
  if (VALID_COLUMNS.indexOf(ticket.column) === -1) {
    throw new RangeError('unknown column "' + ticket.column + '" at index ' + index);
  }
  if (VALID_ACTIONS.indexOf(ticket.action) === -1) {
    throw new RangeError('unknown action "' + ticket.action + '" at index ' + index);
  }
  if (ticket.priority !== undefined) {
    if (typeof ticket.priority !== 'string') {
      throw new TypeError('priority at index ' + index + ' must be a string');
    }
  }
  return ticket;
}

function nextColumn(ticket) {
  const column = ticket.column;
  const action = ticket.action;

  if (action === 'start') {
    if (column === 'backlog') {
      return 'progress';
    }
  }
  if (action === 'review') {
    if (ticket.priority === 'urgent') {
      return 'testing';
    }
  }
  if (action === 'approve') {
    if (column === 'testing') {
      return 'done';
    }
  }
  if (action === 'reject') {
    if (column === 'testing') {
      return 'progress';
    }
  }
  if (action === 'archive') {
    if (column === 'done') {
      return 'archived';
    }
  }
  return column;
}

function update(tickets) {
  if (!Array.isArray(tickets)) {
    throw new TypeError('tickets must be an array');
  }
  return tickets.map(function (ticket, index) {
    return nextColumn(validateTicket(ticket, index));
  });
}

function describeTransitions(tickets) {
  const columns = update(tickets);
  return columns.map(function (column, index) {
    const from = tickets[index].column;
    const id = tickets[index].id;
    const label = id === undefined ? '#' + index : id;
    if (column === from) {
      return label + ': stays in ' + from;
    }
    return label + ': ' + from + ' -> ' + column;
  });
}

function countBy(columns, target) {
  return columns.filter(function (column) {
    return column === target;
  }).length;
}

const board = [
  { id: 'T-1', column: 'backlog', action: 'start', priority: 'low' },
  { id: 'T-2', column: 'progress', action: 'review', priority: 'urgent' },
  { id: 'T-3', column: 'testing', action: 'approve', priority: 'normal' },
  { id: 'T-4', column: 'testing', action: 'reject', priority: 'urgent' },
  { id: 'T-5', column: 'done', action: 'archive', priority: 'low' },
  { id: 'T-6', column: 'backlog', action: 'archive', priority: 'normal' }
];

const updated = update(board);
describeTransitions(board).forEach(function (line) {
  console.log(line);
});
console.log('in testing: ' + countBy(updated, 'testing'));
console.log('archived: ' + countBy(updated, 'archived'));

module.exports = { update, nextColumn, describeTransitions, countBy };

