function normalizeRecord(record) {
  if (record === null) {
    throw new TypeError('each weapon record must be an object');
  }
  if (typeof record !== 'object') {
    throw new TypeError('each weapon record must be an object');
  }
  const type = typeof record.type === 'string' ? record.type.trim().toLowerCase() : '';
  const material = typeof record.material === 'string' ? record.material.trim().toLowerCase() : '';
  const gem = typeof record.gem === 'string' ? record.gem.trim().toLowerCase() : '';
  if (type === '') {
    throw new Error('weapon record is missing a type');
  }
  return { type: type, material: material, gem: gem };
}

function basePower(type, material) {
  if (type === 'sword') {
    return material === 'steel' ? 60 : 0;
  }
  if (type === 'bow') {
    return material === 'wood' ? 40 : 0;
  }
  if (type === 'shield') {
    return material === 'mithril' ? 80 : 0;
  }
  return 0;
}

function gemBonus(type, gem) {
  if (type === 'staff') {
    return gem === 'ruby' ? 20 : 0;
  }
  if (type === 'dagger') {
    return gem === 'sapphire' ? 15 : 0;
  }
  return 0;
}

function powerOf(record) {
  const weapon = normalizeRecord(record);
  return basePower(weapon.type, weapon.material) + gemBonus(weapon.type, weapon.gem);
}

function enchant(weapons) {
  if (!Array.isArray(weapons)) {
    throw new TypeError('weapons must be an array of records');
  }
  return weapons.map(powerOf);
}

function describe(record, power) {
  const weapon = normalizeRecord(record);
  const parts = [];
  if (weapon.material !== '') {
    parts.push(weapon.material);
  }
  parts.push(weapon.type);
  if (weapon.gem !== '') {
    parts.push('set with ' + weapon.gem);
  }
  const label = parts.join(' ');
  if (power === 0) {
    return label + ': no enchantment';
  }
  return label + ': ' + power + ' power';
}

function report(weapons) {
  const powers = enchant(weapons);
  return weapons.map(function (record, index) {
    return describe(record, powers[index]);
  }).join('\n');
}

const armoury = [
  { type: 'Sword', material: 'steel', gem: '' },
  { type: 'bow', material: 'wood', gem: 'ruby' },
  { type: 'staff', material: 'oak', gem: 'Ruby' },
  { type: 'dagger', material: 'iron', gem: 'sapphire' },
  { type: 'shield', material: 'mithril', gem: 'topaz' },
  { type: 'sword', material: 'wood', gem: 'quartz' }
];

console.log(report(armoury));
console.log('total: ' + enchant(armoury).reduce(function (sum, p) { return sum + p; }, 0));

module.exports = { enchant: enchant, powerOf: powerOf, report: report };

