const SEASONS = ["summer", "winter", "spring", "autumn"];
const WEATHERS = ["clear", "snow", "rain"];
const DAYS = ["weekday", "weekend"];

function validateRequest(request, index) {
  if (Array.isArray(request) !== true) {
    throw new TypeError(`request ${index} is not an array`);
  }
  if (request.length !== 3) {
    throw new RangeError(`request ${index} must have exactly three elements`);
  }
  const [season, weather, day] = request;
  if (SEASONS.indexOf(season) === -1) {
    throw new RangeError(`request ${index} has unknown season "${season}"`);
  }
  if (WEATHERS.indexOf(weather) === -1) {
    throw new RangeError(`request ${index} has unknown weather "${weather}"`);
  }
  if (DAYS.indexOf(day) === -1) {
    throw new RangeError(`request ${index} has unknown day "${day}"`);
  }
}

function requestPrice(season, weather, day) {
  if (season === "summer") {
    return day === "weekend" ? 50 : 40;
  }
  if (season === "winter") {
    if (weather === "snow") {
      return 30;
    }
    return weather === "clear" ? 20 : 0;
  }
  if (season === "spring") {
    return day === "weekend" ? 35 : 25;
  }
  if (weather === "rain") {
    return 15;
  }
  return weather === "clear" ? 25 : 0;
}

function price(requests) {
