'use strict';

const VEHICLE_TYPES = ['car', 'truck', 'motorcycle', 'bus'];
const PERIODS = ['peak', 'offpeak'];

function validateEntry(entry, index) {
  if (Array.isArray(entry) === false) {
    throw new TypeError('Entry ' + index + ' must be an array');
  }
  if (entry.length !== 3) {
    throw new RangeError('Entry ' + index + ' must have exactly three elements');
  }
  const [type, time, hasPass] = entry;
  if (VEHICLE_TYPES.indexOf(type) === -1) {
    throw new RangeError('Entry ' + index + ' has unknown vehicle type: ' + type);
  }
  if (PERIODS.indexOf(time) === -1) {
    throw new RangeError('Entry ' + index + ' has unknown period: ' + time);
  }
  if (typeof hasPass !== 'boolean') {
    throw new TypeError('Entry ' + index + ' must carry a boolean pass flag');
  }
  return { type: type, time: time, hasPass: hasPass };
}

function tollFor(type, time, hasPass) {
  if (hasPass === false) {
    if (type === 'car') {
      return time === 'peak' ? 5 : 3;
    }
    if (type === 'truck') {
      return time === 'peak' ? 10 : 7;
    }
    if (type === 'motorcycle') {
      return 2;
    }
  }
  if (type === 'bus') {
    if (time === 'peak') {
      return 8;
    }
  }
  if (type === 'truck') {
    return 2;
  }
  return 0;
}

function collect(vehicles) {
  if (Array.isArray(vehicles) === false) {
    throw new TypeError('collect expects a list of vehicle records');
  }
  let total = 0;
  for (let i = 0; i < vehicles.length; i += 1) {
    const record = validateEntry(vehicles[i], i);
    total += tollFor(record.type, record.time, record.hasPass);
  }
  return total;
}

function formatReport(vehicles) {
  const lines = vehicles.map(function (entry, index) {
    const record = validateEntry(entry, index);
    const amount = tollFor(record.type, record.time, record.hasPass);
    const note = record.hasPass === true ? 'pass' : 'cash';
    return record.type + ' (' + record.time + ', ' + note + '): ' + amount;
  });
  lines.push('total: ' + collect(vehicles));
  return lines.join('\n');
}

function main() {
  const gate = [['car', 'peak', false], ['truck', 'offpeak', true], ['motorcycle', 'peak', true]];
  console.log(formatReport(gate));
  const nightShift = [['bus', 'peak', true], ['bus', 'offpeak', false], ['truck', 'peak', false]];
  console.log(formatReport(nightShift));
  const balanced = collect(gate) === collect(nightShift);
  console.log('gates match: ' + balanced);
}

main();

