const TICKET_TYPES = ["foot", "car", "rv", "commercial"];
const VEHICLE_SIZES = ["none", "standard", "oversized"];

function validatePassenger(entry) {
  if (!Array.isArray(entry) || entry.length !== 3) {
    return "entry must have exactly three elements";
  }
  const [ticket, size, resident] = entry;
  if (TICKET_TYPES.indexOf(ticket) === -1) {
    return "unknown ticket type: " + String(ticket);
  }
  if (VEHICLE_SIZES.indexOf(size) === -1) {
    return "unknown vehicle size: " + String(size);
  }
  if (typeof resident !== "boolean") {
    return "residency flag must be a boolean";
  }
  return null;
}

function fareFor(entry) {
  const [ticket, size, resident] = entry;
  if (ticket === "foot") {
    return resident === true ? [1, 0] : [1, 5];
  }
  if (ticket === "car") {
    return resident ? [5, 10] : [5, 20];
  }
  if (ticket === "rv") {
    if (size === "oversized") {
      return [10, 50];
    }
    if (size === "standard") {
      return [8, 40];
    }
    return null;
  }
  if (size === "oversized") {
    return [15, 80];
  }
  if (resident === true) {
    return [10, -10];
  }
  return null;
}

function board(passengers) {
  let load = 0;
  let earnings = 0;
  for (const entry of passengers) {
    if (validatePassenger(entry) !== null) {
      continue;
    }
    const fare = fareFor(entry);
    if (fare === null) {
      continue;
    }
    load += fare[0];
    earnings += fare[1];
  }
  return [load, earnings];
}

function formatReport(passengers) {
  const problems = [];
  for (const entry of passengers) {
    const message = validatePassenger(entry);
    if (message !== null) {
      problems.push(message);
    } else if (fareFor(entry) === null) {
      problems.push("no fare rule for " + JSON.stringify(entry));
    }
  }
  const [load, earnings] = board(passengers);
  const lines = ["load=" + load, "earnings=" + earnings];
  if (problems.length === 0) {
    lines.push("all arrivals boarded");
  } else {
    lines.push("skipped " + problems.length + ": " + problems.join("; "));
  }
  return lines.join("\n");
}

