function validateBatch(batch, index) {
  if (!Array.isArray(batch)) {
    throw new TypeError(`batch ${index} must be an array`);
  }
  if (batch.length !== 3) {
    throw new RangeError(`batch ${index} must have exactly three elements`);
  }
  const [pastry, filling, frozen] = batch;
  if (typeof pastry !== "string") {
    throw new TypeError(`batch ${index}: pastry must be a string`);
  }
  if (typeof filling !== "string") {
    throw new TypeError(`batch ${index}: filling must be a string`);
  }
  if (typeof frozen !== "boolean") {
    throw new TypeError(`batch ${index}: frozen must be a boolean`);
  }
  return [pastry.trim().toLowerCase(), filling.trim().toLowerCase(), frozen];
}

function batchMinutes(pastry, filling, frozen) {
  if (pastry === "croissant") {
    if (!frozen && filling === "none") return 15;
    if (frozen && filling === "chocolate") return 25;
    return 0;
  }
  if (pastry === "muffin") {
    if (filling === "berry") return 20;
    if (!frozen && filling === "none") return 18;
    return 0;
  }
  if (pastry === "tart") {
    if (filling === "fruit") return 30;
    if (frozen && filling === "cream") return 40;
    return 0;
  }
  if (pastry === "bread") {
    return frozen ? 60 : 45;
  }
  return 0;
}

function bake(batches) {
  if (!Array.isArray(batches)) {
    throw new TypeError("batches must be an array");
  }
  let total = 0;
  batches.forEach((batch, index) => {
    const [pastry, filling, frozen] = validateBatch(batch, index);
    total += batchMinutes(pastry, filling, frozen);
  });
  return total;
}

function summarize(batches) {
  const perPastry = new Map();
  batches.forEach((batch, index) => {
    const [pastry, filling, frozen] = validateBatch(batch, index);
    const entry = perPastry.get(pastry) || { count: 0, minutes: 0 };
    entry.count += 1;
    entry.minutes += batchMinutes(pastry, filling, frozen);
    perPastry.set(pastry, entry);
  });
  const lines = [];
  for (const [pastry, entry] of perPastry) {
    const label = entry.count === 1 ? "batch" : "batches";
    const note = entry.minutes === 0 ? " (no recipe match)" : "";
    lines.push(`${pastry}: ${entry.count} ${label}, ${entry.minutes} min${note}`);
  }
  const minutes = bake(batches);
  lines.push(`total: ${minutes} min (${(minutes / 60).toFixed(2)} h)`);
  return lines;
}

const schedule = [
  ["croissant", "chocolate", true],
  ["muffin", "berry", false],
  ["bread", "none", true],
];

summarize(schedule).forEach((line) => console.log(line));

