'use strict';

const BREADS = ['white', 'wheat', 'rye'];

function normalize(value) {
  return typeof value === 'string' ? value.trim().toLowerCase() : value;
}

function validateSandwich(sandwich, index) {
  if (!Array.isArray(sandwich)) {
    throw new TypeError(`Order item ${index} must be an array.`);
  }
  if (sandwich.length !== 3) {
    throw new TypeError(`Order item ${index} must have exactly three elements.`);
  }
  const [bread, meat, toasted] = sandwich;
  if (typeof bread !== 'string') {
    throw new TypeError(`Order item ${index} has a non-string bread.`);
  }
  if (typeof meat !== 'string') {
    throw new TypeError(`Order item ${index} has a non-string meat.`);
  }
  if (typeof toasted !== 'boolean') {
    throw new TypeError(`Order item ${index} has a non-boolean toasted flag.`);
  }
  if (BREADS.indexOf(normalize(bread)) === -1) {
    throw new RangeError(`Order item ${index} uses unknown bread "${bread}".`);
  }
  return [normalize(bread), normalize(meat), toasted];
}

function priceOf(bread, meat, toasted) {
  if (bread === 'white') {
    if (meat === 'turkey') {
      if (!toasted) return 6;
    }
    if (meat === 'ham' && toasted) return 7;
  }
  if (bread === 'wheat') {
    if (meat === 'beef') return 8;
    if (meat === 'veggie' && !toasted) return 5;
  }
  if (bread === 'rye') {
    if (meat === 'pastrami' && toasted) return 10;
    if (meat === 'turkey') return 9;
  }
  if (meat === 'none') {
    if (toasted) return 4;
    if (bread === 'wheat') return 3;
  }
  return 0;
}

function assemble(sandwiches) {
  if (!Array.isArray(sandwiches)) {
    throw new TypeError('assemble expects a list of sandwiches.');
  }
  let total = 0;
  for (let i = 0; i < sandwiches.length; i += 1) {
    const [bread, meat, toasted] = validateSandwich(sandwiches[i], i);
    total += priceOf(bread, meat, toasted);
  }
  return total;
}

function describe(sandwich) {
  const [bread, meat, toasted] = validateSandwich(sandwich, 0);
  const filling = meat === 'none' ? 'no meat' : meat;
  const state = toasted ? 'toasted' : 'cold';
  const price = priceOf(bread, meat, toasted);
  const label = price === 0 ? 'not on the menu' : `$${price}`;
  return `${bread} bread, ${filling}, ${state}: ${label}`;
}

function report(order) {
  const lines = order.map(describe);
  lines.push(`Total: $${assemble(order)}`);
  return lines.join('\n');
}

const order = [['white', 'ham', true], ['wheat', 'beef', false], ['rye', 'pastrami', true]];
console.log(report(order));

