function validateWheel(wheel, index) {
  if (!Array.isArray(wheel)) {
    throw new TypeError(`wheel ${index} is not an array`);
  }
  if (wheel.length != 3) {
    throw new TypeError(`wheel ${index} must have exactly three elements`);
  }
  const [type, milk, washed] = wheel;
  if (typeof type != "string") {
    throw new TypeError(`wheel ${index} has a non-string cheese type`);
  }
  if (typeof milk != "string") {
    throw new TypeError(`wheel ${index} has a non-string milk`);
  }
  if (typeof washed != "boolean") {
    throw new TypeError(`wheel ${index} has a non-boolean washed flag`);
  }
  if (CHEESE_TYPES.indexOf(type) == -1) {
    throw new RangeError(`wheel ${index} has unknown cheese type "${type}"`);
  }
  if (MILK_KINDS.indexOf(milk) == -1) {
    throw new RangeError(`wheel ${index} has unknown milk "${milk}"`);
  }
}

function wheelWeeks([type, milk, washed]) {
  if (type == "brie") {
    if (milk == "cow") {
      return washed == false ? 4 : 0;
    }
    return milk == "goat" ? 6 : 0;
