function pelletsFor(species, stage, morning) {
  if (species === "salmon") {
    if (stage === "adult") return 50;
    if (stage === "fry" && morning) return 10;
    return 0;
  }
  if (species === "trout") {
    if (stage === "adult") return morning ? 40 : 0;
    if (stage === "fry") return morning ? 0 : 8;
    return 0;
  }
  if (species === "tilapia") {
    if (stage === "adult") return 30;
    if (stage === "fry" && morning) return 5;
    return 0;
  }
  if (species === "catfish") {
    if (stage === "fry") return 6;
    if (stage === "adult") return morning ? 0 : 25;
  }
  return 0;
}

const KNOWN_SPECIES = ["salmon", "trout", "tilapia", "catfish"];

function validateTank(tank, index) {
  if (!Array.isArray(tank)) {
    throw new TypeError(`tank ${index} must be an array`);
  }
  if (tank.length !== 3) {
    throw new TypeError(`tank ${index} must have exactly three elements`);
  }
  const [species, stage, morning] = tank;
  if (typeof species !== "string") {
    throw new TypeError(`tank ${index} species must be a string`);
  }
  if (typeof stage !== "string") {
    throw new TypeError(`tank ${index} stage must be a string`);
  }
  if (typeof morning !== "boolean") {
    throw new TypeError(`tank ${index} morning flag must be a boolean`);
  }
  if (KNOWN_SPECIES.indexOf(species) === -1) {
    throw new TypeError(`tank ${index} has unknown species "${species}"`);
  }
  return { species, stage, morning };
}

function feed(tanks) {
  let totalPellets = 0;
  tanks.forEach((tank, index) => {
    const { species, stage, morning } = validateTank(tank, index);
    totalPellets += pelletsFor(species, stage, morning);
  });
  return totalPellets;
}

function summarize(tanks) {
  const bySpecies = new Map();
  tanks.forEach((tank, index) => {
    const { species, stage, morning } = validateTank(tank, index);
    if (bySpecies.has(species) === false) {
      bySpecies.set(species, { pellets: 0, fry: 0, adult: 0 });
    }
    const entry = bySpecies.get(species);
    entry.pellets += pelletsFor(species, stage, morning);
    if (stage === "fry") {
      entry.fry += 1;
    } else if (stage === "adult") {
      entry.adult += 1;
    }
  });
