const BET_TYPES = ["win", "place", "show", "exact"];
const RANKS = ["first", "second", "third"];

function validateBet(bet, index) {
  if (!Array.isArray(bet)) {
    throw new TypeError("bet " + index + " must be an array");
  }
  if (bet.length != 3) {
    throw new RangeError("bet " + index + " must have exactly three elements");
  }
  const [type, rank, favorite] = bet;
  if (typeof type != "string") {
    throw new TypeError("bet " + index + " must start with a bet type string");
  }
  if (typeof rank != "string") {
    throw new TypeError("bet " + index + " must contain a rank string");
  }
  if (typeof favorite != "boolean") {
    throw new TypeError("bet " + index + " must end with a favorite flag");
  }
  if (BET_TYPES.indexOf(type) == -1) {
    throw new RangeError("unknown bet type: " + type);
  }
  if (RANKS.indexOf(rank) == -1) {
    throw new RangeError("unknown rank: " + rank);
  }
}

function betValue(type, rank, favorite) {
  if (type == "win") {
    if (rank == "first") {
      return favorite ? 20 : 50;
    }
  } else if (type == "place") {
    if (rank == "first") {
      return 10;
    }
    if (rank == "second" && !favorite) {
      return 30;
    }
  } else if (type == "show") {
    if (rank == "first") {
      return 5;
    }
    if (rank == "second") {
      return 12;
    }
    if (rank == "third" && favorite) {
      return 8;
    }
  } else if (rank == "second") {
    return 0;
  }
  return 0;
}

function payout(bets) {
  if (!Array.isArray(bets)) {
    throw new TypeError("bets must be an array");
  }
  let total = 0;
  bets.forEach((bet, index) => {
    validateBet(bet, index);
    total += betValue(bet[0], bet[1], bet[2]);
  });
  return total;
}

function describeBet(bet) {
  const value = betValue(bet[0], bet[1], bet[2]);
  const runner = bet[2] == true ? "favorite" : "longshot";
  const money = value == 0 ? "no payout" : "$" + value;
  return bet[0] + " / " + bet[1] + " (" + runner + "): " + money;
}

function summarize(bets) {
  const counts = {};
  for (const bet of bets) {
    counts[bet[0]] = (counts[bet[0]] || 0) + 1;
  }
  return BET_TYPES
    .filter((type) => counts[type] != undefined)
    .map((type) => counts[type] + " " + type + (counts[type] == 1 ? " ticket" : " tickets"))
    .join(", ");
}

const tickets = [["win", "first", false], ["place", "second", false], ["show", "third", true]];
tickets.forEach((bet) => console.log(describeBet(bet)));
console.log("Held: " + summarize(tickets));
console.log("Total payout: " + payout(tickets));

