const LOCKED = 'locked';
const UNLOCKED = 'unlocked';

function validateAction(action) {
  if (!Array.isArray(action)) {
    return 'action must be an array';
  }
  if (action.length !== 2) {
    return 'action must contain a name and a ticket type';
  }
  const [name, ticket] = action;
  if (typeof name !== 'string') {
    return 'action name must be a string';
  }
  if (typeof ticket !== 'string') {
    return 'ticket type must be a string';
  }
  return null;
}

function transition(state, name, ticket) {
  if (name === 'override') {
    if (ticket === 'admin') {
      return { state: UNLOCKED, entered: false };
    }
  }
  if (state === LOCKED) {
    if (name === 'insert') {
      if (ticket === 'coin') {
        return { state: UNLOCKED, entered: false };
      }
    }
    if (name === 'scan') {
      if (ticket === 'pass') {
        return { state: UNLOCKED, entered: false };
      }
    }
    return { state: LOCKED, entered: false };
  }
  if (name === 'push') {
    if (ticket === 'none') {
      return { state: LOCKED, entered: true };
    }
  }
  return { state: UNLOCKED, entered: false };
}

function process(actions) {
  if (!Array.isArray(actions)) {
    throw new TypeError('actions must be an array');
  }
  let state = LOCKED;
  let entries = 0;
  actions.forEach((action, index) => {
    const problem = validateAction(action);
    if (problem !== null) {
      throw new TypeError('action ' + index + ': ' + problem);
    }
    const result = transition(state, action[0], action[1]);
    state = result.state;
    if (result.entered) {
      entries += 1;
    }
  });
  return entries;
}

function describeRun(label, actions) {
  const entries = process(actions);
  const noun = entries === 1 ? 'entry' : 'entries';
  return label + ': ' + entries + ' successful ' + noun;
}

function main() {
  const runs = [
    ['coin then push', [['insert', 'coin'], ['push', 'none']]],
    ['push while locked', [['push', 'none'], ['scan', 'pass'], ['push', 'none']]],
    ['admin override', [['override', 'admin'], ['push', 'none'], ['push', 'none']]],
    ['wrong ticket', [['insert', 'pass'], ['push', 'none']]]
  ];
  runs.forEach(([label, actions]) => {
    console.log(describeRun(label, actions));
  });
}

main();

