function fahrenheitToCelsius(value) {
  return (value - 32) * 5 / 9;
}

function normalizeTemperature(value, unit) {
  if (unit === 'fahrenheit') {
    return fahrenheitToCelsius(value);
  }
  if (unit === 'kelvin') {
    return value - 273.15;
  }
  return value;
}

function normalizePressure(value, unit) {
  if (unit === 'psi') {
    return value * 68.95;
  }
  return value;
}

function normalizeWind(value, unit) {
  if (unit === 'knots') {
    return value * 1.852;
  }
  return value;
}

function isIgnored(sensor, value) {
  if (sensor === 'error') {
    return true;
  }
  return value === -99;
}

function log(readings) {
  const processed = [];
  for (const reading of readings) {
    const [sensor, value, unit] = reading;
    if (typeof value !== 'number' || Number.isNaN(value)) {
      continue;
    }
    if (isIgnored(sensor, value)) {
      continue;
    }
    if (sensor === 'temperature') {
      processed.push(normalizeTemperature(value, unit));
    } else if (sensor === 'pressure') {
      processed.push(normalizePressure(value, unit));
    } else if (sensor === 'wind') {
      processed.push(normalizeWind(value, unit));
    } else {
      processed.push(value);
    }
  }
  return processed;
}

function formatReport(values) {
  if (values.length === 0) {
    return 'no usable readings';
  }
  return values.map(v => (Math.round(v * 100) / 100).toFixed(2)).join(', ');
}

const batch = [
  ['temperature', 32, 'fahrenheit'],
  ['temperature', 300, 'kelvin'],
  ['temperature', 21.5, 'celsius'],
  ['pressure', 14.7, 'psi'],
  ['pressure', 1013, 'hPa'],
  ['wind', 10, 'knots'],
  ['wind', 5, 'm/s'],
  ['error', 500, 'celsius'],
  ['humidity', -99, 'percent'],
  ['humidity', 48, 'percent']
];

const standardized = log(batch);
console.log(formatReport(standardized));
console.log('discarded: ' + (batch.length - standardized.length));

