const PHASES = ['normal', 'end'];

function checkDie(value, index, slot) {
  if (typeof value !== 'number') {
    throw new TypeError(`roll ${index}: ${slot} die must be a number`);
  }
  if (value !== Math.trunc(value)) {
    throw new RangeError(`roll ${index}: ${slot} die must be an integer`);
  }
  if (value < 1 || value > 6) {
    throw new RangeError(`roll ${index}: ${slot} die must be between 1 and 6`);
  }
}

function validateRoll(entry, index) {
  if (Array.isArray(entry) === false) {
    throw new TypeError(`roll ${index}: expected an array`);
  }
  if (entry.length !== 3) {
    throw new TypeError(`roll ${index}: expected [first, second, phase]`);
  }
  const phase = entry[2];
  if (typeof phase !== 'string') {
    throw new TypeError(`roll ${index}: phase must be a string`);
  }
  if (PHASES.indexOf(phase) === -1) {
    throw new RangeError(`roll ${index}: unknown phase "${phase}"`);
  }
  checkDie(entry[0], index, 'first');
  checkDie(entry[1], index, 'second');
}

function roll(dice) {
  let position = 0;
  let consecutiveDoubles = 0;
  for (let i = 0; i < dice.length; i += 1) {
    validateRoll(dice[i], i);
    const [first, second, phase] = dice[i];
    const isDouble = first === second;
    const sum = first + second;
    if (isDouble && phase === 'normal') {
      position += sum;
      consecutiveDoubles += 1;
    } else if (!isDouble) {
      consecutiveDoubles = 0;
    }
    if (consecutiveDoubles === 3) {
      position = -1;
      break;
    }
    if (isDouble && first === 1) {
      position -= 50;
    }
    if (isDouble && first === 6) {
      position += 50;
    }
    if (phase === 'end') {
      if (sum === 7) {
        position += 10;
      }
    }
  }
  return position;
}

function describePosition(position) {
  if (position === -1) {
    return 'sent to jail (three consecutive doubles)';
  }
  if (position < 0) {
    return `${position} (behind the start)`;
  }
  return String(position);
}

function main() {
  const games = [
    [[3, 3, 'normal']],
    [[1, 1, 'normal'], [2, 4, 'normal']],
    [[6, 6, 'normal'], [4, 3, 'end']],
    [[2, 2, 'normal'], [5, 5, 'normal'], [4, 4, 'normal'], [1, 6, 'end']]
  ];
  games.forEach((game, index) => {
    console.log(`game ${index + 1}: ${describePosition(roll(game))}`);
  });
}

main();

