VALID_STATES = ['idle', 'loaded', 'warming', 'running', 'projecting'];

const TRANSITIONS = [
  { name: 'thread film', sw: 'off', from: 'idle', to: 'loaded' },
  { name: 'power lamp', sw: 'on', from: 'loaded', to: 'warming' },
  { name: 'start motor', sw: 'on', from: 'warming', to: 'running' },
  { name: 'open shutter', sw: 'active', from: 'running', to: 'projecting' },
];

function normalizeAction(action) {
  if (!Array.isArray(action) || action.length !== 2) {
    return null;
  }
  const [name, sw] = action;
  if (typeof name !== 'string') {
    return null;
  }
  if (typeof sw !== 'string') {
    return null;
  }
  return { name: name.trim().toLowerCase(), sw: sw.trim().toLowerCase() };
}

function matches(rule, step, state) {
  if (rule.name !== step.name) {
    return false;
  }
  if (rule.sw !== step.sw) {
    return false;
  }
  return rule.from === state;
}

function nextState(state, step) {
  for (const rule of TRANSITIONS) {
    if (matches(rule, step, state)) {
      return rule.to;
    }
  }
  return state;
}

function project(actions) {
  let state = 'idle';
  if (!Array.isArray(actions)) {
    return state;
  }
  for (const action of actions) {
    const step = normalizeAction(action);
    if (step === null) {
      continue;
    }
    state = nextState(state, step);
  }
  return state;
}

function describe(state) {
  if (state === 'projecting') {
    return 'film is on screen';
  }
  const index = VALID_STATES.indexOf(state);
  const remaining = VALID_STATES.length - 1 - index;
  return `${state} (${remaining} step${remaining === 1 ? '' : 's'} to projecting)`;
}

function report(sequences) {
  const lines = [];
  for (const sequence of sequences) {
    const final = project(sequence);
    const labels = sequence.map((a) => (normalizeAction(a) === null ? '?' : a.join(' ')));
    lines.push(`[${labels.join(', ')}] -> ${final}: ${describe(final)}`);
  }
  return lines.join('\n');
}

const runs = [
  [['thread film', 'off'], ['power lamp', 'on']],
  [['power lamp', 'on'], ['thread film', 'off']],
  [['thread film', 'off'], ['power lamp', 'on'], ['start motor', 'on'], ['open shutter', 'active']],
  [['thread film', 'off'], ['start motor', 'on'], ['open shutter', 'active']],
  [['thread film', 'off'], ['power lamp', 'ON'], ['start motor', 'on'], 'rewind'],
];

console.log(report(runs));

