  }
  if (typeof distance !== 'string') {
    throw new TypeError('Distance must be a string');
  }
  return { name, distance };
}

function applyAction(progress, name, distance) {
  if (name === 'hold') {
    const gain = ROAST_GAINS[distance];
    if (typeof gain === 'number') {
      progress.level += gain;
    }
  } else if (name === 'rotate') {
    if (distance === 'above') {
      progress.rotations += 1;
    }
  }
}

