function manufacture(parts) {
  let validScreens = 0;
  let validBatteries = 0;
  let validCameras = 0;

  for (const part of parts) {
    const name = part[0];
    const supplier = part[1];

    if (name === 'damaged') {
      return false;
    }
    if (name === 'screen' && supplier === 'alpha') {
      validScreens += 1;
    } else if (name === 'battery' && supplier === 'beta') {
      validBatteries += 1;
    } else if (name === 'camera' && supplier === 'gamma') {
      validCameras += 1;
    }
  }

  return validScreens === 1 && validBatteries === 1 && validCameras === 2;
}

function parsePart(line) {
  const tokens = line.trim().split(/\s+/);
  if (tokens.length !== 2) {
    throw new Error('each part needs a name and a supplier: "' + line + '"');
  }
  return [tokens[0].toLowerCase(), tokens[1].toLowerCase()];
}

function parseOrder(text) {
  return text
    .split(',')
    .map((chunk) => chunk.trim())
    .filter((chunk) => chunk.length !== 0)
    .map(parsePart);
}

function missingReport(parts) {
  const needed = { screen: 1, battery: 1, camera: 2 };
  const found = { screen: 0, battery: 0, camera: 0 };
  const expected = { screen: 'alpha', battery: 'beta', camera: 'gamma' };

  for (const [name, supplier] of parts) {
    if (expected[name] === supplier) {
      found[name] += 1;
    }
  }

  const notes = [];
  for (const name of Object.keys(needed)) {
    const gap = needed[name] - found[name];
    if (gap > 0) {
      notes.push('need ' + gap + ' more ' + name + ' from ' + expected[name]);
    } else if (gap !== 0) {
      notes.push('too many ' + name + ' units by ' + -gap);
    }
  }
  return notes;
}

function describeOrder(text) {
  const parts = parseOrder(text);
  const ok = manufacture(parts);
  if (ok === true) {
    return text + ' -> assembly valid';
  }
  const damaged = parts.some((part) => part[0] === 'damaged');
  if (damaged) {
    return text + ' -> rejected: damaged component present';
  }
  return text + ' -> rejected: ' + missingReport(parts).join('; ');
}

const orders = [
  'screen alpha, battery beta, camera gamma, camera gamma',
  'screen alpha, battery beta, camera gamma',
  'screen alpha, battery omega, camera gamma, camera gamma, damaged none',
  'screen alpha, screen alpha, battery beta, camera gamma, camera gamma'
];

for (const order of orders) {
  console.log(describeOrder(order));
}

