const EVENT_NAMES = ['start', 'heat', 'cool', 'check', 'hold', 'drop', 'error', 'stop'];
const NO_OP_EVENTS = ['check', 'hold'];

function parseEvent(entry) {
  if (!Array.isArray(entry)) {
    throw new TypeError('each event must be an array');
  }
  if (entry.length != 2) {
    throw new RangeError('each event must hold a name and a temperature');
  }
  const [name, degrees] = entry;
  if (typeof name != 'string') {
    throw new TypeError('event name must be a string');
  }
  if (typeof degrees != 'number' || Number.isNaN(degrees)) {
    throw new TypeError(`temperature for "${name}" must be a number`);
  }
  if (EVENT_NAMES.indexOf(name) == -1) {
    throw new Error(`unknown event: ${name}`);
  }
  return { name, degrees };
}

function roast(events) {
  let temperature = 0;
  let running = false;
  for (const entry of events) {
    const { name, degrees } = parseEvent(entry);
    if (NO_OP_EVENTS.includes(name)) {
      continue;
    }
    if (name == 'start') {
      if (running == false) {
        running = true;
      }
    } else if (name == 'heat') {
      if (running == true) {
        temperature += degrees;
      }
    } else if (name == 'cool') {
      if (temperature > 0) {
        temperature -= degrees;
      }
    } else if (name == 'drop') {
      return temperature;
    } else if (name == 'error') {
      return -1;
    } else if (name == 'stop') {
      running = false;
    }
  }
  return temperature;
}

function describe(label, result) {
  const status = result == -1 ? 'aborted' : 'complete';
  return `${label}: ${status} at ${result} degrees`;
}

function summarize(runs) {
  let aborted = 0;
  let hottest = null;
  for (const run of runs) {
    if (run.result == -1) {
      aborted += 1;
      continue;
    }
    if (hottest == null || run.result > hottest.result) {
      hottest = run;
    }
  }
  const peak = hottest == null ? 'none' : `${hottest.label} (${hottest.result})`;
  return `runs: ${runs.length}, aborted: ${aborted}, peak: ${peak}`;
}

function main() {
  const batches = [
    { label: 'city', events: [['start', 0], ['heat', 50], ['drop', 0]] },
    { label: 'full city', events: [['start', 0], ['heat', 120], ['check', 0], ['cool', 20], ['stop', 0], ['heat', 90]] },
    { label: 'vienna', events: [['start', 0], ['heat', 80], ['hold', 80], ['error', 0], ['drop', 0]] }
  ];
  const runs = batches.map(({ label, events }) => ({ label, result: roast(events) }));
  for (const run of runs) {
    console.log(describe(run.label, run.result));
  }
  console.log(summarize(runs));
}

