const MINUTES = {
  rock: 5,
  pop: 4,
  jazz: 6,
  blues: 5,
  country: 4,
  classical: 10,
  metal: 6,
  disco: 7
};

function normalizeButton(label) {
  if (typeof label !== 'string') {
    throw new TypeError('Each button must be a string, got: ' + typeof label);
  }
  return label.trim().toLowerCase();
}

function analyze(buttons) {
  if (Array.isArray(buttons) === false) {
    throw new TypeError('buttons must be an array of button names');
  }
  let total = 0;
  let premium = true;
  const played = [];
  const ignored = [];
  for (const label of buttons) {
    const name = normalizeButton(label);
    if (name === 'skip') {
      premium = false;
      continue;
    }
    const duration = MINUTES[name];
    if (duration === undefined) {
      throw new Error('Unknown button: ' + name);
    }
    if (premium === false) {
      ignored.push(name);
    } else {
      total += duration;
      played.push(name);
    }
  }
  return { total, premium, played, ignored };
}

function play(buttons) {
  return analyze(buttons).total;
}

function formatDuration(minutes) {
  if (minutes === 0) {
    return '0 minutes';
  }
  const hours = Math.floor(minutes / 60);
  const rest = minutes % 60;
  const parts = [];
  if (hours > 0) {
    parts.push(hours + (hours === 1 ? ' hour' : ' hours'));
  }
  if (rest > 0) {
    parts.push(rest + (rest === 1 ? ' minute' : ' minutes'));
  }
  return parts.join(' ');
}

function describe(buttons) {
  const report = analyze(buttons);
  const lines = [];
  if (report.played.length === 0) {
    lines.push('Played: nothing');
  } else {
    lines.push('Played: ' + report.played.join(', '));
  }
  if (report.ignored.length !== 0) {
    lines.push('Ignored after skip: ' + report.ignored.join(', '));
  }
