const VESSEL_TYPES = ["barge", "sailboat", "military", "kayak", "ferry", "tanker"];
const TIDES = ["low", "mid", "high"];
const SIGNALS = ["horn", "radio", "flare", "silence"];

function validateRecord(record, index) {
  if (Array.isArray(record) !== true) {
    throw new TypeError(`record ${index} is not a list`);
  }
  if (record.length !== 3) {
    throw new RangeError(`record ${index} must hold type, tide and signal`);
  }
  const [type, tide, signal] = record;
  if (VESSEL_TYPES.indexOf(type) === -1) {
    throw new RangeError(`record ${index} has unknown vessel type "${type}"`);
  }
  if (TIDES.indexOf(tide) === -1) {
    throw new RangeError(`record ${index} has unknown tide "${tide}"`);
  }
  if (SIGNALS.indexOf(signal) === -1) {
    throw new RangeError(`record ${index} has unknown signal "${signal}"`);
  }
  return { type, tide, signal };
}

function operate(vessels) {
  let wear = 0;
  let delay = 0;
  vessels.forEach((record, index) => {
    const { type, tide, signal } = validateRecord(record, index);
    if (type === "barge") {
      if (signal === "horn") {
        wear += 10;
      }
    }
    if (tide === "high") {
      if (type === "sailboat") {
        delay += 20;
      }
    }
    if (signal === "radio") {
      if (type === "military") {
        wear += 5;
      }
    }
    if (type !== "kayak") {
      if (tide === "low") {
        delay += 15;
      }
    }
    if (signal === "flare") {
      if (tide !== "low") {
        delay -= 5;
      }
    }
    if (type === "ferry") {
      if (signal === "silence") {
        wear += 50;
      }
    }
  });
  return [wear, delay];
}

