function parseEntry(entry) {
  if (!Array.isArray(entry) || entry.length !== 3) {
    throw new TypeError('each log entry must be [system, status, depth]');
  }
  const [system, status, depth] = entry;
  if (typeof system !== 'string') {
    throw new TypeError('system must be a string');
  }
  if (typeof status !== 'string') {
    throw new TypeError('status must be a string');
  }
  if (typeof depth !== 'number' || Number.isNaN(depth)) {
    throw new TypeError('depth must be a number');
  }
  return { system: system.toLowerCase(), status: status.toLowerCase(), depth };
}

function dive(logs) {
  let oxygen = 100;
  let safe = true;

  for (const entry of logs) {
    const { system, status, depth } = parseEntry(entry);

    if (system === 'comms') {
      if (status === 'offline') {
        safe = false;
      }
    } else if (system === 'valve') {
      if (depth > 50) {
        oxygen -= 10;
      }
    } else if (system === 'hatch') {
      if (depth !== 0) {
        safe = false;
      }
    } else if (system === 'oxygen') {
      if (status === 'venting') {
        oxygen -= 5;
      }
    } else if (system === 'ballast') {
      if (depth === 100) {
        safe = true;
      }
    }

    if (system !== 'comms') {
      if (status === 'failed') {
        oxygen -= 20;
      }
    }
  }

  return [oxygen, safe];
}

function describe(result) {
  const [oxygen, safe] = result;
  const condition = safe === true ? 'SAFE' : 'UNSAFE';
  const margin = oxygen === 100 ? 'full reserves' : `${oxygen}% reserves`;
  return `${condition} with ${margin}`;
}

function main() {
  const dives = [
    [['valve', 'open', 60], ['comms', 'offline', 60], ['ballast', 'filling', 100]],
    [['hatch', 'sealed', 12], ['oxygen', 'venting', 12], ['pump', 'failed', 12]],
    [['comms', 'failed', 0], ['ballast', 'empty', 0]]
  ];

  for (const logs of dives) {
    const result = dive(logs);
    console.log(`${JSON.stringify(result)} -> ${describe(result)}`);
  }
}

main();

