function validateStep(step, index) {
  if (Array.isArray(step) !== true) {
    throw new TypeError('step ' + index + ' must be an array');
  }
  if (step.length !== 3) {
    throw new RangeError('step ' + index + ' must hold component, action, inspector');
  }
  for (const field of step) {
    if (typeof field !== 'string') {
      throw new TypeError('step ' + index + ' must contain only strings');
    }
  }
  return step.map((field) => field.trim().toLowerCase());
}

function pack(steps) {
  let score = 0;
  let complete = false;
  for (let i = 0; i < steps.length; i += 1) {
    const [component, action, inspector] = validateStep(steps[i], i);
    if (component === 'canopy') {
      if (action === 'folded') {
        score += 10;
      }
    }
    if (component === 'lines') {
      if (action === 'tangled') {
        score -= 20;
      }
    }
    if (inspector === 'chief') {
      if (component === 'reserve') {
        score += 15;
      }
    }
    if (action === 'sealed') {
      if (component === 'container') {
        complete = true;
      }
    }
    if (inspector === 'novice') {
      if (action === 'skipped') {
        score -= 30;
      }
    }
    if (component !== 'harness') {
      if (action === 'damaged') {
        score -= 50;
      }
    }
    if (component === 'slider') {
      if (action === 'missing') {
        complete = false;
      }
    }
  }
  return [score, complete];
}

function formatReport(steps) {
  const [score, complete] = pack(steps);
  const verdict = complete === true ? 'SEALED' : 'OPEN';
  const grade = score >= 0 ? 'safe' : 'unsafe';
  return 'score=' + score + ' status=' + verdict + ' (' + grade + ')';
}

function main() {
  const rigs = [
    [['canopy', 'folded', 'chief'], ['reserve', 'checked', 'chief'], ['container', 'sealed', 'novice']],
    [['lines', 'tangled', 'novice'], ['slider', 'missing', 'chief'], ['container', 'sealed', 'chief']],
    [['harness', 'damaged', 'chief'], ['canopy', 'damaged', 'novice'], ['reserve', 'skipped', 'novice']],
