const KNOWN_METALS = ["iron", "steel", "bronze"];
const KNOWN_BELLOWS = ["stopped", "slow", "medium", "fast"];

function normalizeAction(action, index) {
  if (!Array.isArray(action)) {
    throw new TypeError("action " + index + " must be an array");
  }
  if (action.length !== 3) {
    throw new RangeError("action " + index + " needs metal, color and bellows");
  }
  const parts = action.map(function (field) {
    if (typeof field !== "string") {
      throw new TypeError("action " + index + " has a non-string field");
    }
    return field.trim().toLowerCase();
  });
  if (KNOWN_METALS.indexOf(parts[0]) === -1) {
    throw new RangeError("unknown metal: " + parts[0]);
  }
  if (KNOWN_BELLOWS.indexOf(parts[2]) === -1) {
    throw new RangeError("unknown bellows speed: " + parts[2]);
  }
  return parts;
}

function applyAction(state, metal, color, bellows) {
  if (metal === "iron") {
    if (color === "cherry") state.purity += 10;
  }
  if (metal === "steel") {
    if (bellows === "fast") state.purity += 20;
  }
  if (color === "orange") {
    if (bellows === "stopped") state.purity -= 10;
  }
  if (metal === "bronze") {
    if (color !== "yellow") state.purity -= 5;
  }
  if (bellows === "fast") {
    if (metal !== "steel") state.carbon += 2;
  }
  if (color === "black") {
    state.purity = 0;
    state.carbon = 0;
  }
  if (bellows === "medium") {
    if (metal === "iron") state.purity += 5;
  }
  return state;
}

function smelt(actions) {
  if (!Array.isArray(actions)) {
    throw new TypeError("actions must be an array of actions");
  }
  const state = { purity: 0, carbon: 0 };
  actions.forEach(function (action, index) {
    const parts = normalizeAction(action, index);
    applyAction(state, parts[0], parts[1], parts[2]);
  });
  return [state.purity, state.carbon];
}

function describe(result) {
  const purity = result[0];
  const carbon = result[1];
  if (purity === 0) {
    if (carbon === 0) return "quenched";
    return "sooty";
  }
  if (purity < 0) return "ruined";
  if (carbon === 0) return "clean";
  return "workable";
}

function formatReport(actions) {
  const result = smelt(actions);
  const steps = actions.length === 1 ? "1 step" : actions.length + " steps";
  return steps + ": purity " + result[0] + ", carbon " + result[1] + " (" + describe(result) + ")";
}

const forgeLog = [
  ["iron", "cherry", "slow"],
  ["steel", "white", "fast"],
  ["bronze", "orange", "stopped"]
];

console.log(smelt(forgeLog).join(", "));
console.log(formatReport(forgeLog));
console.log(formatReport([["iron", "black", "medium"], ["bronze", "yellow", "fast"]]));

