const STATES = ["perched", "hunting", "diving", "returning", "soaring"];

function validateMovement(movement, index) {
  if (Array.isArray(movement) !== true) {
    throw new TypeError(`movement ${index} must be an array`);
  }
  if (movement.length !== 3) {
    throw new TypeError(`movement ${index} must hold state, altitude and prey`);
  }
  const [state, altitude, prey] = movement;
  if (typeof state !== "string") {
    throw new TypeError(`movement ${index} has a non-string state`);
  }
  if (STATES.indexOf(state) === -1) {
    throw new RangeError(`movement ${index} has unknown state "${state}"`);
  }
  if (Number.isFinite(altitude) === false) {
    throw new TypeError(`movement ${index} has a non-numeric altitude`);
  }
  if (typeof prey !== "string") {
    throw new TypeError(`movement ${index} has a non-string prey`);
  }
  return { state, altitude, prey };
}

function track(movements) {
  let energy = 100;
  let success = 0;

  movements.forEach((movement, index) => {
    const { state, altitude, prey } = validateMovement(movement, index);

    if (state === "perched") {
      if (prey === "none") {
        energy += 10;
      }
    } else if (state === "hunting") {
      if (prey === "rabbit") {
        energy -= 15;
      }
    } else if (state === "diving") {
      if (altitude === 0) {
        success += 30;
      }
    } else if (state === "returning") {
      if (prey !== "none") {
        success += 10;
      }
    }

    if (prey === "pigeon") {
      if (state !== "perched") {
        energy -= 10;
      }
    }

    if (state === "soaring" && altitude > 100) {
      energy -= 2;
    }
  });

  return [energy, success];
}

function describeFlight(movements) {
  const [energy, success] = track(movements);
  const condition = energy === 100 ? "fresh" : energy > 50 ? "steady" : "spent";
  return `energy=${energy} (${condition}), success=${success}`;
}

