function validateReading(reading, index) {
  if (Array.isArray(reading) !== true) {
    throw new TypeError(`reading ${index} is not a list`);
  }
  if (reading.length !== 3) {
    throw new RangeError(`reading ${index} must hold exactly three fields`);
  }
  const [state, wind, grid] = reading;
  if (STATES.indexOf(state) === -1) {
    throw new RangeError(`reading ${index} has unknown turbine state "${state}"`);
  }
  if (WINDS.indexOf(wind) === -1) {
    throw new RangeError(`reading ${index} has unknown wind category "${wind}"`);
  }
  if (GRIDS.indexOf(grid) === -1) {
    throw new RangeError(`reading ${index} has unknown grid status "${grid}"`);
  }
  return { state, wind, grid };
}

function regulate(readings) {
  let power = 0;
  let stress = 0;

  readings.forEach((raw, index) => {
    const { state, wind, grid } = validateReading(raw, index);

    if (state === "facing") {
      if (grid === "connected") {
        power += 50;
      }
    } else if (state === "yawing") {
      if (wind === "high") {
        stress += 5;
      }
    } else if (state === "braked") {
      if (grid === "offline") {
        stress -= 10;
      }
    } else if (wind === "storm") {
      if (state !== "feathered") {
        stress += 100;
      }
    } else if (state === "storm") {
      if (grid === "connected") {
        stress -= 20;
      }
    } else if (grid === "disconnected") {
      if (state !== "braked") {
        stress += 30;
      }
    }
  });

  return [power, stress];
}

function describe(result) {
  const [power, stress] = result;
  const load = stress === 0 ? "nominal" : stress < 0 ? "relieved" : "loaded";
  return `power=${power} stress=${stress} (${load})`;
}

function main() {
