const DIRECTIONS = ['left', 'right', 'center'];
const FORCES = ['weak', 'strong'];

function parseTick(raw) {
  let direction;
  let force;
  if (typeof raw === 'string') {
    const parts = raw.trim().toLowerCase().split(/\s+/);
    if (parts.length !== 2) {
      throw new Error('a tick string must hold a direction and a force: ' + raw);
    }
    direction = parts[0];
    force = parts[1];
  } else if (raw && typeof raw === 'object') {
    direction = String(raw.direction).toLowerCase();
    force = String(raw.force).toLowerCase();
  } else {
    throw new Error('a tick must be a string or an object');
  }
  if (DIRECTIONS.indexOf(direction) === -1) {
    throw new Error('unknown swing direction: ' + direction);
  }
  if (FORCES.indexOf(force) === -1) {
    throw new Error('unknown driving force: ' + force);
  }
  return { direction: direction, force: force };
}

function simulate(ticks) {
  let pallet = 'none';
  let swings = 0;
  let wear = 0;
  let stalled = false;
  for (const raw of ticks) {
    if (stalled) {
      break;
    }
    const tick = parseTick(raw);
    if (tick.direction === 'center') {
      continue;
    }
    if (tick.direction === 'left') {
      if (pallet !== 'entry') {
        pallet = 'entry';
        swings += 1;
        if (tick.force === 'weak') {
          stalled = true;
        }
      }
    } else if (pallet === 'entry') {
      pallet = 'exit';
      swings += 1;
    }
    if (pallet === 'exit') {
      if (tick.force === 'strong') {
        wear += 1;
      }
    }
  }
  return [swings, wear];
}

function formatReport(label, result) {
  const swings = result[0];
  const wear = result[1];
  const swingWord = swings === 1 ? 'swing' : 'swings';
  const wearWord = wear === 1 ? 'notch' : 'notches';
  return label + ': ' + swings + ' successful ' + swingWord + ', ' + wear + ' wear ' + wearWord;
}

function main() {
  const stalling = ['right strong', 'left weak', 'right strong'];
  const running = [
    'left strong',
    'right strong',
    'center strong',
    'left strong',
    { direction: 'right', force: 'strong' }
  ];
  console.log(formatReport('stalling escapement', simulate(stalling)));
  console.log(formatReport('running escapement', simulate(running)));
  console.log(formatReport('resting pendulum', simulate(['center weak', 'center strong'])));
}

main();

