const KNOWN_SOURCES = ['deep space', 'local', 'interference'];
const POLARIZATIONS = ['circular', 'linear', 'unpolarized'];

function normalize(text) {
  return typeof text === 'string' ? text.trim().toLowerCase() : '';
}

function describeSource(pulse) {
  const source = normalize(pulse.source);
  if (source === '') {
    return 'unknown';
  }
  return KNOWN_SOURCES.indexOf(source) === -1 ? 'unknown' : source;
}

function describePolarization(pulse) {
  const polarization = normalize(pulse.polarization);
  return POLARIZATIONS.indexOf(polarization) === -1 ? 'unpolarized' : polarization;
}

function widthOf(pulse) {
  const width = Number(pulse.width);
  return Number.isFinite(width) ? width : 0;
}

function filter(pulses) {
  const validPulsars = [];
  const anomalies = [];
  for (const pulse of pulses) {
    const source = describeSource(pulse);
    if (source === 'unknown') {
      anomalies.push(pulse);
      continue;
    }
    const polarization = describePolarization(pulse);
    if (polarization === 'unpolarized') {
      continue;
    }
    if (source !== 'deep space') {
      continue;
    }
    const width = widthOf(pulse);
    if (polarization === 'circular') {
      validPulsars.push(width);
    } else if (width === 0 || width > 100) {
      anomalies.push(width);
    }
  }
  return [validPulsars, anomalies];
}

function report(pulses) {
  const [validPulsars, anomalies] = filter(pulses);
  const lines = [];
  lines.push(`pulsars: ${validPulsars.length === 0 ? 'none' : validPulsars.join(', ')}`);
  for (const anomaly of anomalies) {
    if (typeof anomaly === 'number') {
      lines.push(`anomaly: linear width ${anomaly}`);
    } else {
      const raw = normalize(anomaly.source);
      lines.push(`anomaly: source "${raw === '' ? '?' : raw}"`);
    }
  }
  return lines.join('\n');
}

const sweep = [
  { source: 'local', polarization: 'circular', width: 42 },
  { source: 'deep space', polarization: 'circular', width: 10 },
];
