  { priority: 'low', destination: 'local', content: 'BIRTHDAY WISHES' },
  { priority: 'low', destination: 'remote', content: 'WEATHER CHATTER' },
  { priority: 'high', destination: 'Testing', content: 'LINE CHECK' },
  { priority: 'high', destination: 'moon', content: 'LOST SIGNAL' }
];

console.log(formatReport(route(traffic)));

