    rear = nextR;
  }
  return { front, rear, ignored };
}

function shift(actions) {
  const result = run(actions);
  return [result.front, result.rear];
}

function summarize(actions) {
  const result = run(actions);
  const label = actions.length == 0 ? '(no actions)' : actions.join(', ');
  const noun = result.ignored == 1 ? 'action' : 'actions';
  return `${label} -> ${result.front}/${result.rear} (${result.ignored} ${noun} ignored)`;
}

