const FONT_TAGS = {
  italic: 'em',
  bold: 'strong',
  underline: 'u'
};

const INDENT = '    ';

function isFontModifier(token) {
  return Object.prototype.hasOwnProperty.call(FONT_TAGS, token);
}

function wrapWord(word, font) {
  if (font === 'roman') {
    return word;
  }
  const tag = FONT_TAGS[font];
  return '<' + tag + '>' + word + '</' + tag + '>';
}

function typeset(characters) {
  if (!Array.isArray(characters)) {
    throw new TypeError('typeset expects an array of character inputs');
  }
  const page = [];
  let font = 'roman';
  let line = '';
  for (const token of characters) {
    if (typeof token !== 'string') {
      throw new TypeError('every character input must be a string');
    }
    if (isFontModifier(token)) {
      font = token;
    } else if (token === 'reset') {
      font = 'roman';
    } else if (token === 'clear') {
      line = '';
    } else if (token === 'indent') {
      line = INDENT + line;
    } else if (token === 'break') {
      page.push(line);
      line = '';
    } else if (line.length === 0) {
      line += wrapWord(token, font);
    } else {
      line += ' ' + wrapWord(token, font);
    }
  }
  if (line !== '') {
    page.push(line);
  }
  return page;
}

function plainText(line) {
  return line.replace(/<\/?(?:em|strong|u)>/g, '');
}

function renderPage(page) {
  return page
    .map((line, index) => {
      const number = String(index + 1).padStart(3, ' ');
      const body = line.length === 0 ? '(blank)' : line;
      return number + ' | ' + body;
    })
    .join('\n');
}

function summarize(page) {
  let words = 0;
  let indented = 0;
  for (const line of page) {
    const text = plainText(line);
    if (text.slice(0, INDENT.length) === INDENT) {
      indented += 1;
    }
    const trimmed = text.trim();
    if (trimmed !== '') {
      words += trimmed.split(/\s+/).length;
    }
  }
  return { lines: page.length, words, indented };
}

const manuscript = [
  'indent', 'The', 'bold', 'Printing', 'Press', 'reset', 'break',
  'italic', 'moves', 'underline', 'metal', 'reset', 'type', 'break',
  'oops', 'clear', 'indent', 'and', 'then', 'rests'
];

const page = typeset(manuscript);
console.log(renderPage(page));
const stats = summarize(page);
console.log(`${stats.lines} lines, ${stats.words} words, ${stats.indented} indented`);

