function normalizeTrend(trend) {
  if (typeof trend !== 'string') {
    throw new TypeError('trend must be a string');
  }
  const value = trend.trim().toLowerCase();
  const allowed = ['falling', 'rising', 'steady'];
  if (allowed.indexOf(value) === -1) {
    throw new RangeError(`unknown pressure trend: ${trend}`);
  }
  return value;
}

function normalizeWind(wind) {
  if (typeof wind !== 'string') {
    throw new TypeError('wind must be a string');
  }
  const value = wind.trim().toLowerCase();
  const allowed = ['calm', 'north', 'south', 'east', 'west'];
  if (allowed.indexOf(value) === -1) {
    throw new RangeError(`unknown wind direction: ${wind}`);
  }
  return value;
}

function forecastFor(trend, wind) {
  if (wind === 'calm') {
    return 'fog';
  }
  if (trend === 'falling') {
    if (wind === 'south') {
      return 'severe storms';
    }
    if (wind === 'east') {
      return 'heavy rain';
    }
    return 'unsettled';
  }
  if (trend === 'rising') {
    if (wind === 'north') {
      return 'clear and cool';
    }
    if (wind === 'west') {
      return 'fair and breezy';
    }
    return 'improving';
  }
  return wind === 'south' ? 'warmer temperatures' : 'no change';
}

function predict(observations) {
  if (!Array.isArray(observations)) {
    throw new TypeError('observations must be an array');
  }
  return observations.map((obs) => {
    const trend = normalizeTrend(obs.trend);
    const wind = normalizeWind(obs.wind);
    return forecastFor(trend, wind);
  });
}

function report(observations, forecasts) {
  const lines = [];
  for (let i = 0; i < observations.length; i += 1) {
    const obs = observations[i];
    const detail = obs.wind === 'calm' ? 'calm air' : `${obs.wind} wind`;
    lines.push(`${obs.trend} pressure, ${detail} -> ${forecasts[i]}`);
  }
  return lines.join('\n');
}

const samples = [
  { trend: 'falling', wind: 'south' },
  { trend: 'falling', wind: 'east' },
  { trend: 'rising', wind: 'north' },
  { trend: 'rising', wind: 'west' },
  { trend: 'steady', wind: 'south' },
  { trend: 'steady', wind: 'east' },
  { trend: 'rising', wind: 'calm' }
];

const outlooks = predict(samples);
console.log(report(samples, outlooks));
const foggy = outlooks.filter((f) => f === 'fog').length;
console.log(`fog forecasts: ${foggy} of ${outlooks.length}`);

