const HARDNESS_CODES = { f: 'soft', '4f': 'soft', '1f': 'medium', p: 'hard', k: 'hard', i: 'hard' };
const WET_LEVELS = ['wet', 'very wet', 'soaked'];

function normalizeText(value, field) {
  if (typeof value !== 'string') {
    throw new TypeError('layer.' + field + ' must be a string');
  }
  return value.trim().toLowerCase();
}

function hardnessClass(hardness) {
  const key = normalizeText(hardness, 'hardness');
  const mapped = HARDNESS_CODES[key];
  if (mapped !== undefined) {
    return mapped;
  }
  if (key === 'soft') {
    return 'soft';
  }
  if (key === 'hard') {
    return 'hard';
  }
  return 'medium';
}

function isWeakLayer(layer) {
  if (normalizeText(layer.shape, 'shape') !== 'facets') {
    return false;
  }
  return hardnessClass(layer.hardness) === 'soft';
}

function isSlabLayer(layer) {
  if (normalizeText(layer.shape, 'shape') !== 'rounds') {
    return false;
  }
  return hardnessClass(layer.hardness) === 'hard';
}

function isWet(layer) {
  const level = normalizeText(layer.wetness, 'wetness');
  return WET_LEVELS.indexOf(level) !== -1;
}

function assess(layers) {
  if (Array.isArray(layers) === false) {
    throw new TypeError('layers must be an array');
  }
  let criticalDanger = 0;
  let slipHazard = 0;
  for (let i = 0; i < layers.length; i += 1) {
    const layer = layers[i];
    const shape = normalizeText(layer.shape, 'shape');
    if (shape === 'ice') {
      if (hardnessClass(layer.hardness) === 'hard') {
        criticalDanger += 2;
      }
    }
    if (shape === 'surface hoar') {
      if (isWet(layer)) {
        slipHazard += 1;
      }
    }
    if (shape === 'crust') {
      criticalDanger = Math.max(0, criticalDanger - 1);
    }
    const below = layers[i + 1];
    if (below !== undefined && isWeakLayer(layer) && isSlabLayer(below)) {
      criticalDanger += 1;
    }
  }
  return { criticalDanger: criticalDanger, slipHazard: slipHazard };
}

function report(layers) {
  const result = assess(layers);
  const verdict = result.criticalDanger === 0 ? 'stable' : 'unstable';
  return 'critical danger ' + result.criticalDanger +
    ', slip hazard ' + result.slipHazard + ' -> ' + verdict;
}

const profile = [
  { shape: 'Surface Hoar', hardness: 'F', wetness: 'wet' },
  { shape: 'rounds', hardness: 'P', wetness: 'dry' },
  { shape: 'facets', hardness: '4F', wetness: 'dry' },
  { shape: 'rounds', hardness: 'K', wetness: 'dry' },
  { shape: 'ice', hardness: 'hard', wetness: 'moist' },
  { shape: 'crust', hardness: '1F', wetness: 'dry' }
];

console.log(report(profile));

module.exports = { assess: assess, report: report, isWeakLayer: isWeakLayer, isSlabLayer: isSlabLayer };

