'use strict';

const ALLOWED = {
  approach: ['perfect', 'steady', 'unsteady'],
  takeoff: ['clean', 'low', 'balked'],
  flight: ['tucked', 'piked', 'straight'],
  entry: ['ripped', 'clean', 'splashy']
};

const PHASE_NAMES = ['approach', 'takeoff', 'flight', 'entry'];

function normalizeQuality(value, phaseName) {
  if (typeof value !== 'string') {
    throw new TypeError('Quality for ' + phaseName + ' must be a string');
  }
  return value.trim().toLowerCase();
}

function readPhases(phases) {
  if (phases === null || typeof phases !== 'object') {
    throw new TypeError('phases must be an object describing the four dive phases');
  }
  const read = {};
  for (const name of PHASE_NAMES) {
    const quality = normalizeQuality(phases[name], name);
    if (ALLOWED[name].indexOf(quality) === -1) {
      throw new RangeError('Unknown ' + name + ' quality: ' + quality);
    }
    read[name] = quality;
  }
  return read;
}

function score(phases) {
  const dive = readPhases(phases);
  let total = 10;
  if (dive.approach === 'perfect') {
    total += 2;
  } else if (dive.approach === 'unsteady') {
    total -= 2;
  }
  if (dive.takeoff === 'balked') {
    return 0;
  }
  if (dive.takeoff === 'low') {
    total -= 3;
  }
  if (dive.flight === 'tucked') {
    total += 1;
  } else if (dive.flight === 'straight') {
    total += 2;
  }
  if (dive.entry === 'ripped') {
    total += 3;
  } else if (dive.entry === 'splashy') {
    total -= dive.flight === 'straight' ? 2 : 4;
  }
  return total;
}

function grade(points) {
  if (points === 0) {
    return 'no dive';
  }
  if (points >= 14) {
    return 'excellent';
  }
  return points >= 10 ? 'solid' : 'flawed';
}

function formatReport(phases) {
  const dive = readPhases(phases);
  const points = score(phases);
  const parts = [dive.approach, dive.takeoff, dive.flight, dive.entry].join(' / ');
  let note = '';
  if (dive.entry === 'splashy' && dive.flight === 'straight') {
    note = ' (partial redemption)';
  } else if (dive.takeoff === 'balked') {
    note = ' (balk)';
  }
  return parts + ' -> ' + points + ' ' + grade(points) + note;
}

function main() {
  const dives = [
    { approach: 'unsteady', takeoff: 'clean', flight: 'straight', entry: 'splashy' },
    { approach: 'perfect', takeoff: 'clean', flight: 'straight', entry: 'ripped' },
    { approach: 'steady', takeoff: 'low', flight: 'tucked', entry: 'splashy' },
    { approach: 'Perfect', takeoff: 'balked', flight: 'piked', entry: 'clean' }
  ];
  for (const dive of dives) {
    console.log(formatReport(dive));
  }
}

main();

module.exports = { score, grade, formatReport };

