function normalize(value) {
  return typeof value === 'string' ? value.trim().toLowerCase() : '';
}

function validateClaim(claim, index) {
  if (typeof claim !== 'object') {
    throw new TypeError('Claim at index ' + index + ' is not an object');
  }
  if (claim === null) {
    throw new TypeError('Claim at index ' + index + ' is missing');
  }
  const status = normalize(claim.policyStatus);
  if (status === '') {
    throw new TypeError('Claim at index ' + index + ' has no policy status');
  }
  return {
    status: status,
    network: normalize(claim.providerNetwork),
    category: normalize(claim.serviceCategory)
  };
}

function decideActive(network, category) {
  if (network === 'internal') {
    return 'approved';
  }
  if (category === 'emergency') {
    return 'approved';
  }
  return 'pending';
}

function decideClaim(claim, index) {
  const parts = validateClaim(claim, index);
  if (parts.category === 'cosmetic') {
    return 'denied';
  }
  if (parts.status === 'expired') {
    return 'denied';
  }
  if (parts.status === 'terminated') {
    return 'denied';
  }
  if (parts.status === 'suspended') {
    return parts.category === 'preventive' ? 'approved' : 'pending';
  }
  if (parts.status === 'active') {
    return decideActive(parts.network, parts.category);
  }
  throw new RangeError('Unknown policy status "' + parts.status + '" at index ' + index);
}

function adjudicate(claims) {
  if (!Array.isArray(claims)) {
    throw new TypeError('adjudicate expects an array of claims');
  }
  return claims.map(decideClaim);
}

function summarize(decisions) {
  const counts = { approved: 0, pending: 0, denied: 0 };
  for (const decision of decisions) {
    counts[decision] += 1;
  }
  const shown = ['approved', 'pending', 'denied'].filter(function (key) {
    return counts[key] !== 0;
  });
  if (shown.length === 0) {
    return 'no claims processed';
  }
  return shown.map(function (key) {
    return key + ': ' + counts[key];
  }).join(', ');
}

const batch = [
  { policyStatus: 'Active', providerNetwork: 'internal', serviceCategory: 'routine' },
  { policyStatus: 'active', providerNetwork: 'external', serviceCategory: 'routine' },
  { policyStatus: 'active', providerNetwork: 'external', serviceCategory: 'emergency' },
  { policyStatus: 'suspended', providerNetwork: 'internal', serviceCategory: 'preventive' },
  { policyStatus: 'suspended', providerNetwork: 'external', serviceCategory: 'routine' },
  { policyStatus: 'terminated', providerNetwork: 'internal', serviceCategory: 'emergency' },
  { policyStatus: 'expired', providerNetwork: 'internal', serviceCategory: 'preventive' },
  { policyStatus: 'active', providerNetwork: 'internal', serviceCategory: 'Cosmetic' }
];

const results = adjudicate(batch);
results.forEach(function (decision, i) {
  console.log('Claim ' + (i + 1) + ' -> ' + decision);
});
console.log('Summary: ' + summarize(results));

