const MATERIALS = ['glass', 'polycarbonate', 'high index', 'plastic'];

function normalize(value) {
  if (value === undefined) {
    return '';
  }
  if (value === null) {
    return '';
  }
  return String(value).toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
}

function settingFor(order) {
  const material = normalize(order.material);
  const shape = normalize(order.shape);
  const coating = normalize(order.coating);

  if (MATERIALS.indexOf(material) === -1) {
    throw new Error('unknown lens material: ' + material);
  }

  if (material === 'high index') {
    if (coating === 'anti reflective') {
      return 'premium';
    }
    if (coating === 'tinted') {
      return 'custom';
    }
    return 'delicate';
  }

  if (material === 'glass') {
    if (shape === 'spherical') {
      return 'standard';
    }
    if (coating === 'scratch resistant') {
      return 'reinforced';
    }
  }

  if (material === 'polycarbonate') {
    if (shape === 'aspheric') {
      return 'advanced';
    }
  }

  if (material === 'plastic') {
    if (shape === 'cylindrical') {
      return 'basic';
    }
  }

  return 'unsupported';
}

function grind(prescriptions) {
  return prescriptions.map(settingFor);
}

function describe(order) {
  const coating = normalize(order.coating);
  const base = normalize(order.material) + ' / ' + normalize(order.shape);
  if (coating === '') {
    return base + ' / no coating';
  }
  return base + ' / ' + coating;
}

function report(prescriptions) {
  const settings = grind(prescriptions);
  const lines = settings.map((setting, index) => describe(prescriptions[index]) + ' -> ' + setting);
  const unsupported = settings.filter((setting) => setting === 'unsupported').length;
  if (unsupported === 0) {
    lines.push('all ' + settings.length + ' orders matched a machine setting');
  } else {
    lines.push(unsupported + ' of ' + settings.length + ' orders need manual review');
  }
  return lines.join('\n');
}

const orders = [
  { material: 'glass', shape: 'spherical', coating: null },
  { material: 'Polycarbonate', shape: 'aspheric', coating: 'tinted' },
  { material: 'high-index', shape: 'cylindrical', coating: 'anti reflective' },
  { material: 'high index', shape: 'spherical', coating: 'scratch resistant' },
  { material: 'glass', shape: 'aspheric', coating: 'scratch resistant' },
  { material: 'plastic', shape: 'cylindrical' },
  { material: 'plastic', shape: 'aspheric', coating: 'tinted' }
];

console.log(report(orders));

module.exports = { grind, settingFor, report };

