const FLIGHT_TYPES = ['domestic', 'international', 'charter', 'cargo', 'military'];
const WEIGHT_CLASSES = ['standard', 'oversized'];
const TRANSFER_STATUSES = ['final', 'transit'];

function parseBag(spec) {
  const parts = spec.split('/').map((part) => part.trim().toLowerCase());
  if (parts.length !== 3) {
    throw new Error(`bag spec must have three fields: ${spec}`);
  }
  const [flightType, weightClass, transferStatus] = parts;
  if (FLIGHT_TYPES.indexOf(flightType) === -1) {
    throw new Error(`unknown flight type: ${flightType}`);
  }
  if (WEIGHT_CLASSES.indexOf(weightClass) === -1) {
    throw new Error(`unknown weight class: ${weightClass}`);
  }
  if (TRANSFER_STATUSES.indexOf(transferStatus) === -1) {
    throw new Error(`unknown transfer status: ${transferStatus}`);
  }
  return { flightType, weightClass, transferStatus };
}

function chuteFor(bag) {
  if (bag.flightType === 'charter') {
    return 'special';
  }
  if (bag.flightType === 'military') {
    return 'secure';
  }
  if (bag.transferStatus === 'transit') {
    return bag.weightClass === 'oversized' ? 'manual' : 'expedited';
  }
  if (bag.flightType === 'domestic') {
    return 'primary';
  }
  if (bag.flightType === 'international') {
    return 'secondary';
  }
  if (bag.flightType === 'cargo') {
    return 'warehouse';
  }
  return 'manual';
}

function route(bags) {
  return bags.map((bag) => chuteFor(bag));
}

function summarize(chutes) {
  const counts = new Map();
  for (const chute of chutes) {
    counts.set(chute, (counts.get(chute) || 0) + 1);
  }
  const lines = [...counts.entries()]
    .sort((a, b) => (a[0] < b[0] ? -1 : 1))
    .map(([chute, count]) => `${chute}: ${count}`);
  return lines.join(', ');
}

function main() {
  const specs = [
    'domestic/standard/final',
    'international/oversized/final',
    'international/standard/transit',
    'domestic/oversized/transit',
    'charter/oversized/transit',
    'cargo/oversized/final',
    'military/standard/transit'
  ];
  const bags = specs.map(parseBag);
  const chutes = route(bags);
  chutes.forEach((chute, index) => {
    const bag = bags[index];
    const note = chute === 'manual' ? ' (hand-carry to belt)' : '';
    console.log(`${bag.flightType}/${bag.weightClass}/${bag.transferStatus} -> ${chute}${note}`);
  });
  console.log(`totals: ${summarize(chutes)}`);
}

main();

