const PROFILES = {
  dim: 'dim',
  bright: 'bright',
  standard: 'standard',
  soft: 'soft',
  glare: 'glare reduction',
  ambient: 'ambient',
  fallback: 'neutral'
};

function normalizeField(value) {
  if (typeof value !== 'string') {
    return '';
  }
  return value.trim().toLowerCase();
}

function validateArtwork(artwork, index) {
  if (typeof artwork !== 'object') {
    throw new TypeError('Artwork at index ' + index + ' is not a descriptor object');
  }
  if (artwork === null) {
    throw new TypeError('Artwork at index ' + index + ' is null');
  }
  if (typeof artwork.medium !== 'string') {
    throw new TypeError('Artwork at index ' + index + ' is missing a creative medium');
  }
  if (typeof artwork.framing !== 'string') {
    throw new TypeError('Artwork at index ' + index + ' is missing a framing type');
  }
  return {
    medium: normalizeField(artwork.medium),
    status: normalizeField(artwork.status),
    framing: normalizeField(artwork.framing)
  };
}

function isFragileWatercolor(spec) {
  if (spec.medium !== 'watercolor') {
    return false;
  }
  return spec.status === 'fragile';
}

function isExposed(spec, medium) {
  if (spec.medium !== medium) {
    return false;
  }
  return spec.framing === 'exposed';
}

function profileFor(spec) {
  if (isFragileWatercolor(spec)) {
    return PROFILES.dim;
  }
  if (spec.framing === 'glass') {
    return PROFILES.glare;
  }
  if (isExposed(spec, 'sculpture')) {
    return PROFILES.bright;
  }
  if (spec.medium === 'oil painting') {
    return spec.status === 'restored' ? PROFILES.soft : PROFILES.standard;
  }
  if (spec.medium === 'tapestry') {
    return PROFILES.ambient;
  }
  if (isExposed(spec, 'acrylic')) {
    return PROFILES.bright;
  }
  return PROFILES.fallback;
}

function illuminate(artworks) {
  if (!Array.isArray(artworks)) {
    throw new TypeError('illuminate expects an array of artworks');
  }
  return artworks.map((artwork, index) => profileFor(validateArtwork(artwork, index)));
}

function labelFor(artwork, index) {
  const title = normalizeField(artwork.title);
  if (title === '') {
    return 'Untitled #' + (index + 1);
  }
  return artwork.title.trim();
}

function describeProfiles(artworks) {
  const profiles = illuminate(artworks);
  return profiles.map((profile, index) => {
    const note = profile === PROFILES.fallback ? ' (no rule matched; using house default)' : '';
    return labelFor(artworks[index], index) + ': ' + profile + note;
  });
}

const collection = [
  { title: 'Morning Mist', medium: 'Watercolor', status: 'fragile', framing: 'glass' },
  { title: 'Bronze Runner', medium: 'sculpture', status: 'stable', framing: 'exposed' },
  { title: 'Harbour Light', medium: 'oil painting', status: 'restored', framing: 'wood' },
  { title: 'Quiet Fields', medium: 'oil painting', status: 'stable', framing: 'wood' },
  { title: '', medium: 'tapestry', status: 'stable', framing: 'wood' },
  { title: 'Neon Grid', medium: 'acrylic', status: 'stable', framing: 'exposed' },
  { title: 'Charcoal Study', medium: 'charcoal', status: 'stable', framing: 'mat' }
];

describeProfiles(collection).forEach(line => console.log(line));

module.exports = { illuminate, describeProfiles, PROFILES };

