function normalizeField(value, fieldName) {
  if (typeof value !== 'string') {
    throw new TypeError(`${fieldName} must be a string`);
  }
  return value.trim().toLowerCase();
}

const HULL_STATES = ['intact', 'compromised'];

function parseVessel(raw) {
  if (typeof raw !== 'object') {
    throw new TypeError('each vessel must be an object');
  }
  if (raw === null) {
    throw new TypeError('each vessel must be an object');
  }
  const shipClass = normalizeField(raw.shipClass, 'shipClass');
  const cargoType = normalizeField(raw.cargoType, 'cargoType');
  const hull = normalizeField(raw.hullIntegrity, 'hullIntegrity');
  if (!HULL_STATES.includes(hull)) {
    throw new RangeError(`unknown hull integrity: ${hull}`);
  }
  return { shipClass, cargoType, hull, name: raw.name };
}

function assign(vessel) {
  const intact = vessel.hull === 'intact';
  if (vessel.shipClass === 'freighter' && intact) {
    return 'deep water pier';
  }
  if (vessel.cargoType === 'hazardous' && !intact) {
    return 'quarantine anchorage';
  }
  if (vessel.shipClass === 'passenger') {
    return intact ? 'terminal dock' : 'emergency slip';
  }
  if (vessel.shipClass === 'fishing') {
    if (vessel.cargoType === 'perishable') {
      return 'commercial wharf';
    }
  }
  if (vessel.shipClass === 'military' && intact) {
    return 'naval base';
  }
  if (vessel.shipClass === 'yacht' && intact) {
    return 'marina';
  }
  return 'holding area';
}

function navigate(vessels) {
  if (!Array.isArray(vessels)) {
    throw new TypeError('vessels must be an array');
  }
  return vessels.map(parseVessel).map(assign);
}

function report(vessels, assignments) {
  const lines = [];
  for (let i = 0; i < vessels.length; i += 1) {
    const label = typeof vessels[i].name === 'string' ? vessels[i].name : `vessel ${i + 1}`;
    const berth = assignments[i];
    const note = berth === 'holding area' ? ' (awaiting review)' : '';
    lines.push(`${label} -> ${berth}${note}`);
  }
  const unresolved = assignments.filter((berth) => berth === 'holding area').length;
  lines.push(`${assignments.length} vessel(s) processed, ${unresolved} unresolved`);
  return lines.join('\n');
}

const fleet = [
  { name: 'Ironhold', shipClass: 'Freighter', cargoType: 'ore', hullIntegrity: 'intact' },
  { name: 'Caustic Tide', shipClass: 'freighter', cargoType: 'hazardous', hullIntegrity: 'compromised' },
