    return NaN;
  }

  if (typeof celsius !== 'number') {
    return NaN;
  }

  if (celsius === undefined) {
    return NaN;
  }

  if (isNaN(celsius)) {
    return NaN;
  }

  const offset = 32;

  result = celsius * CONVERSION_FACTOR + offset;

  if (result === Infinity) {
    return Infinity;
  }

  if (result === -Infinity) {
    return -Infinity;
  }

  const zeroCelsius = 0;
  if (celsius === zeroCelsius) {
    return 32;
  }

  const twentyFiveCelsius = 25;
  if (celsius === twentyFiveCelsius) {
    return 77;
  }

  return result;
}

