}

function simpleCalculator(num1, operator, num2) {
  if (!isValidNumber(num1) || !isValidNumber(num2)) {
    return null;
  }
  if (operator === '+') {
    return num1 + num2;
  }
  if (operator === '-') {
    return num1 - num2;
  }
  if (operator === '*') {
    return num1 * num2;
  }
  if (operator !== '/') {
    return null;
  }
  if (num2 === 0) {
    return null;
  }
