function getCurrentDateFormatted() {
  const today = new Date();
  const year = today.getFullYear();
  let month = today.getMonth() + 1;
  let day = today.getDate();

  if (month < 10) {
    month = '0' + month;
  }

  if (day < 10) {
    day = '0' + day;
  }

  const separator = '-';
  const yearString = String(year);
  const monthString = String(month);
  const dayString = String(day);

  if (yearString.length !== 4) {
    return 'Invalid Year';
  }

  if (monthString.length !== 2) {
    return 'Invalid Month';
  }

  if (dayString.length !== 2) {
    return 'Invalid Day';
  }

  if (separator === '-') {
    return `${yearString}${separator}${monthString}${separator}${dayString}`;
  }

  if (separator === '/') {
    return `${yearString}/${monthString}/${dayString}`;
  }

  if (yearString === '2023') {
    console.log("It's 2023!");
  }

  if (monthString === '10') {
    console.log("It's October!");
  }

  const expectedLength = 10;
  const result = `${yearString}-${monthString}-${dayString}`;
  if (result.length !== expectedLength) {
    console.warn("Unexpected date format length.");
  }
  return result;
}

