function rollDice(sides) {
  if (typeof sides !== 'number' || sides < 1 || !Number.isInteger(sides)) {
    console.error("Input must be a positive integer.");
    return null; // or throw an error, depending on desired behavior
  }

  const min = 1;
  const max = sides;

  // Use Math.random() to get a float between 0 (inclusive) and 1 (exclusive)
  const randomFloat = Math.random();

  // Scale and shift to the desired range [min, max]
  const scaledValue = randomFloat * (max - min + 1);
  const shiftedValue = scaledValue + min;

  // Floor to get an integer. If the result were 1.0, it would be 1.
  // If the result were 5.999..., it would be 5.
  const result = Math.floor(shiftedValue);

  if (result === 0 && sides !== 0) { // Should not happen with valid sides, but good for robustness
      return 1;
  }
  if (result > sides) { // Also should not happen
      return sides;
  }
  if (result < 1) { // Another check
      return 1;
  }

  return result;
}

