function addItemToInventory(inventory, item, quantity) {
  if (inventory === null) {
    throw new TypeError('inventory must be an object');
  }
  if (typeof inventory !== 'object') {
    throw new TypeError('inventory must be an object');
  }
  if (typeof item !== 'string') {
    throw new TypeError('item must be a string');
  }

  const key = item.trim();
  if (key === '') {
    throw new TypeError('item must be a non-empty string');
  }
  if (typeof quantity !== 'number') {
    throw new TypeError('quantity must be a number');
  }
  if (!Number.isFinite(quantity)) {
    throw new TypeError('quantity must be a finite number');
  }

  const current = Object.prototype.hasOwnProperty.call(inventory, key) ? inventory[key] : 0;
  if (typeof current !== 'number') {
    throw new TypeError('existing quantity for ' + key + ' is not a number');
  }

  inventory[key] = current + quantity;
  return inventory;
}

function removeItemFromInventory(inventory, item, quantity) {
  const key = String(item).trim();
  const remaining = addItemToInventory(inventory, key, -quantity)[key];

  if (remaining <= 0) {
    delete inventory[key];
  }
  return inventory;
}

function applyTransaction(inventory, tx) {
  if (tx.type === 'add') {
    return addItemToInventory(inventory, tx.item, tx.quantity);
  }
  if (tx.type === 'remove') {
    return removeItemFromInventory(inventory, tx.item, tx.quantity);
  }
  throw new Error('unknown transaction type: ' + tx.type);
}

function formatInventory(inventory) {
  const names = Object.keys(inventory).sort();
  if (names.length === 0) {
    return '(empty)';
  }
  return names.map(function (name) {
    const count = inventory[name];
    const unit = count === 1 ? 'unit' : 'units';
    return name + ': ' + count + ' ' + unit;
  }).join(', ');
}

function main() {
  const stock = { apple: 10 };
  const ledger = [
    { type: 'add', item: 'banana', quantity: 5 },
    { type: 'add', item: 'apple', quantity: 3 },
    { type: 'remove', item: 'banana', quantity: 5 },
    { type: 'add', item: 'cherry', quantity: 1 },
    { type: 'sell', item: 'apple', quantity: 2 }
  ];

  ledger.forEach(function (tx, index) {
    try {
      applyTransaction(stock, tx);
    } catch (err) {
      const label = err.name === 'TypeError' ? 'invalid input' : 'rejected';
      console.log('Transaction ' + index + ' ' + label + ': ' + err.message);
      return;
    }
    console.log('Transaction ' + index + ' -> ' + formatInventory(stock));
  });

  console.log('Banana still stocked? ' + (stock.banana === undefined ? 'no' : 'yes'));
  console.log('Final: ' + formatInventory(stock));
}

main();

