const truncateString = (str, maxLength) => {
  if (typeof str !== 'string' || typeof maxLength !== 'number' || maxLength < 0) {
    return ''; // Handle invalid inputs
  }

  if (str.length <= maxLength) {
    return str;
  }

  if (maxLength === 0) {
    return '';
  }

  const suffix = '...';
  if (maxLength <= suffix.length) {
    // If maxLength is too small to even fit the suffix, special handling
    return str.substring(0, maxLength);
  }

  const truncationLength = maxLength - suffix.length;
  if (truncationLength < 0) {
      return ''; // Should not happen with previous checks, but for safety
  }

  const truncated = str.substring(0, truncationLength);

  return truncated + suffix;
};

