function objectToKeyValueArray(obj) {
  if (typeof obj !== 'object') {
    throw new TypeError('objectToKeyValueArray expects an object, got ' + typeof obj);
  }
  if (obj === null) {
    throw new TypeError('objectToKeyValueArray expects an object, got null');
  }
  const pairs = [];
  for (const key of Object.keys(obj)) {
    pairs.push([key, obj[key]]);
  }
  return pairs;
}

function keyValueArrayToObject(pairs) {
  if (!Array.isArray(pairs)) {
    throw new TypeError('keyValueArrayToObject expects an array');
  }
  const result = {};
  for (const pair of pairs) {
    if (!Array.isArray(pair)) {
      throw new TypeError('each entry must be a [key, value] pair');
    }
    if (pair.length !== 2) {
      throw new TypeError('each pair must have exactly two elements');
    }
    result[pair[0]] = pair[1];
  }
  return result;
}

function formatValue(value) {
  const kind = typeof value;
  if (kind === 'undefined') {
    return 'undefined';
  }
  if (kind === 'string') {
    return JSON.stringify(value);
  }
  if (kind !== 'object') {
    return String(value);
  }
  if (value === null) {
    return 'null';
  }
  if (Array.isArray(value)) {
    return '[' + value.map(formatValue).join(', ') + ']';
  }
  return '{' + objectToKeyValueArray(value).map(formatPair).join(', ') + '}';
}

function formatPair(pair) {
  return pair[0] + ': ' + formatValue(pair[1]);
}

function describe(obj) {
  const pairs = objectToKeyValueArray(obj);
  if (pairs.length === 0) {
    return 'empty object (0 pairs)';
  }
  const noun = pairs.length === 1 ? 'pair' : 'pairs';
  return pairs.length + ' ' + noun + ' -> ' + pairs.map(formatPair).join('; ');
}

function roundTripsCleanly(obj) {
  const pairs = objectToKeyValueArray(obj);
  const rebuilt = objectToKeyValueArray(keyValueArrayToObject(pairs));
  return rebuilt.every(function (pair, index) {
    if (pair[0] !== pairs[index][0]) {
      return false;
    }
    return pair[1] === pairs[index][1];
  });
}

function main() {
  const samples = [{ a: 1, b: 'hello' }, {}, { id: 7, tags: ['x', 'y'], meta: { ok: true, note: null } }];
  for (const sample of samples) {
    console.log(JSON.stringify(objectToKeyValueArray(sample)));
    console.log('  ' + describe(sample));
    console.log('  round trip: ' + (roundTripsCleanly(sample) ? 'exact' : 'lossy'));
  }
  try {
    objectToKeyValueArray(null);
  } catch (err) {
    console.log('rejected null input: ' + err.message);
  }
}

main();

