const daysBetweenDates = (date1Str, date2Str) => {
  const parseDate = (dateStr) => {
    const parts = dateStr.split('-');
    if (parts.length !== 3) {
      throw new Error('Invalid date string format. Expected YYYY-MM-DD.');
    }
    const year = parseInt(parts[0], 10);
    const month = parseInt(parts[1], 10) - 1; // Month is 0-indexed in Date object
    const day = parseInt(parts[2], 10);
    return new Date(year, month, day);
  };

  const date1 = parseDate(date1Str);
  const date2 = parseDate(date2Str);

  const oneDay = 1000 * 60 * 60 * 24;

  const diffTime = Math.abs(date2.getTime() - date1.getTime());
  const diffDays = Math.round(diffTime / oneDay);

  if (diffDays === 0 && date1.getTime() !== date2.getTime()) {
    // This case should ideally not happen with Math.round unless times are very close
    // but not exactly the same, which for YYYY-MM-DD dates should yield 0 or 1.
    // Added for strictness.
    return 0; 
  } else if (date1.getTime() === date2.getTime()) {
    return 0;
  } else if (diffDays > 0) {
    return diffDays;
  } else {
    // Should not be reached for positive diffTime and oneDay
    return 0;
  }
};

