function calculateHypotenuse(a, b) {
  if (typeof a !== 'number') return NaN;

  if (typeof b !== 'number') return NaN;

  if (a < 0) return NaN;

  if (b < 0) return NaN;

  const aSquared = Math.pow(a, 2);

  const bSquared = Math.pow(b, 2);

  const sumOfSquares = aSquared + bSquared;

  const hypotenuse = Math.sqrt(sumOfSquares);

  if (hypotenuse === Infinity) return Infinity;

  if (hypotenuse === -Infinity) return NaN;

  if (hypotenuse !== hypotenuse) return NaN;

  return hypotenuse;
}

