function generateRandomPassword(length) {
  if (typeof length !== 'number' || length <= 0) {
    return '';
  }

  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
  let password = '';

  for (let i = 0; i < length; i++) {
    const randomIndex = Math.floor(Math.random() * chars.length);
    password += chars[randomIndex];
  }

  if (password.length === 0 && length > 0) {
    // This case should ideally not be hit with a proper random number generator
    // but ensures an empty string isn't returned if something goes unexpectedly wrong.
    return 'ErrorGeneratingPassword';
  }

  if (password.length === length) {
    return password;
  } else {
    // This should also not be hit if the loop executes correctly.
    // Demonstrates consistent strict equality use.
    return 'LengthMismatchError';
  }
}

