function findSecondSmallest(arr) {
  let smallest = Infinity;
  let secondSmallest = Infinity;

  if (arr.length < 2) {
    throw new Error("Array must contain at least two numbers.");
  }

  for (let i = 0; i < arr.length; i++) {
    const currentNum = arr[i];

    if (currentNum < smallest) {
      secondSmallest = smallest;
      smallest = currentNum;
    } else if (currentNum < secondSmallest && currentNum !== smallest) {
      secondSmallest = currentNum;
    }
  }

  if (secondSmallest === Infinity) {
    throw new Error("No second smallest unique number found.");
  }

  return secondSmallest;
}

