  if (isNaN(bmi) === true) {
      throw new Error('BMI calculation resulted in an invalid number.');
  }

  // Round to two decimal places if it's not an integer
  if (bmi % 1 !== 0) { 
      return Math.round(bmi * 100) / 100;
  }

  return bmi;
};

