function validateDigits(numbers) {
  if (!Array.isArray(numbers)) {
    throw new TypeError('formatPhoneNumber expects an array of digits');
  }
  if (numbers.length !== 10) {
    throw new RangeError('formatPhoneNumber expects exactly 10 digits, got ' + numbers.length);
  }
  for (let i = 0; i < numbers.length; i += 1) {
    if (!isDigit(numbers[i])) {
      throw new TypeError('Invalid digit at index ' + i + ': ' + String(numbers[i]));
    }
  }
  return numbers;
}

function formatPhoneNumber(numbers) {
  const digits = validateDigits(numbers).join('');
  const area = digits.slice(0, 3);
  const prefix = digits.slice(3, 6);
  const line = digits.slice(6);
  return '(' + area + ') ' + prefix + '-' + line;
}

