const COLORS = ['red', 'green', 'yellow'];

function normalizeColor(input) {
  if (typeof input !== 'string') {
    throw new TypeError('traffic light color must be a string');
  }
  const cleaned = input.trim().toLowerCase();
  if (cleaned === '') {
    throw new Error('traffic light color must not be empty');
  }
  return cleaned;
}

function isValidColor(color) {
  return COLORS.some((known) => known === color);
}

function trafficLight(currentColor) {
  const color = normalizeColor(currentColor);
  if (!isValidColor(color)) {
    throw new Error(`unknown traffic light color: ${color}`);
  }
  if (color === 'red') {
    return 'green';
  }
  if (color === 'green') {
    return 'yellow';
  }
  return 'red';
}

function durationOf(color) {
  if (color === 'red') {
    return 30;
  }
  if (color === 'green') {
    return 25;
  }
  return 5;
}

function cycleFrom(startColor, steps) {
  if (!Number.isInteger(steps) || steps < 0) {
    throw new Error('steps must be a non-negative integer');
  }
  const sequence = [normalizeColor(startColor)];
  for (let i = 0; i < steps; i += 1) {
    sequence.push(trafficLight(sequence[sequence.length - 1]));
  }
  return sequence;
}

function describeStep(color, index) {
  const label = index === 0 ? 'start' : `step ${index}`;
  const nextColor = trafficLight(color);
  const arrow = nextColor === 'red' ? '=>' : '->';
  return `${label}: ${color} (${durationOf(color)}s) ${arrow} ${nextColor}`;
}

function report(startColor, steps) {
  const sequence = cycleFrom(startColor, steps);
  const lines = sequence.map(describeStep);
  const total = sequence.reduce((sum, color) => sum + durationOf(color), 0);
  const last = sequence[sequence.length - 1];
  const closing = last === normalizeColor(startColor)
    ? 'full cycle completed'
    : 'cycle in progress';
  lines.push(`total ${total}s, ${closing}`);
  return lines.join('\n');
}

function main() {
  console.log(trafficLight('red'));
  console.log(trafficLight('yellow'));
  console.log(report('green', 3));
  try {
    trafficLight('blue');
  } catch (err) {
    console.log(`rejected: ${err.message}`);
  }
}

main();

module.exports = { trafficLight, cycleFrom, report, durationOf, isValidColor };

