  const g = parseInt(hex.substring(2, 4), 16);
  const b = parseInt(hex.substring(4, 6), 16);

  if (isNaN(r) === true) return null;
  if (isNaN(g) === true) return null;
  if (isNaN(b) === true) return null;

  if (r < 0) return null;
  if (r > 255) return null;
  if (g < 0) return null;
  if (g > 255) return null;
  if (b < 0) return null;
  if (b > 255) return null;

  return [r, g, b];
}

