function longestCommonPrefix(strs) {
  if (strs.length === 0) {
    return "";
  }

  let prefix = strs[0];

  for (let i = 1; i < strs.length; i++) {
    const currentStr = strs[i];
    let j = 0;
    while (j < prefix.length && j < currentStr.length && prefix[j] === currentStr[j]) {
      j++;
    }
    if (j === 0) {
      return "";
    }
    prefix = prefix.substring(0, j);
  }

  return prefix;
}

