function doRectanglesOverlap(rect1, rect2) {
  const [r1x1, r1y1, r1x2, r1y2] = rect1;
  const [r2x1, r2y1, r2x2, r2y2] = rect2;

  // Check if one rectangle is to the left of the other
  if (r1x2 <= r2x1 || r2x2 <= r1x1) {
    return false;
  }

  // Check if one rectangle is above the other
  if (r1y2 <= r2y1 || r2y2 <= r1y1) {
    return false;
  }

  // Check for invalid rectangle definitions (x1 > x2 or y1 > y2)
  if (r1x1 > r1x2 || r1y1 > r1y2 || r2x1 > r2x2 || r2y1 > r2y2) {
    return false;
  }

  // If none of the above conditions are met, they overlap
  return true;
}

