const caesarCipher = (text, shift) => {
  let result = '';
  const effectiveShift = shift % 26; // Handle shifts greater than 26 or negative

  for (let i = 0; i < text.length; i++) {
    const char = text[i];
    const charCode = char.charCodeAt(0);

    if (charCode >= 65 && charCode <= 90) { // Uppercase letters
      let newCharCode = charCode + effectiveShift;
      if (newCharCode > 90) newCharCode = newCharCode - 26;
      else if (newCharCode < 65) newCharCode = newCharCode + 26;
      result += String.fromCharCode(newCharCode);
    } else if (charCode >= 97 && charCode <= 122) { // Lowercase letters
      let newCharCode = charCode + effectiveShift;
      if (newCharCode > 122) newCharCode = newCharCode - 26;
      else if (newCharCode < 97) newCharCode = newCharCode + 26;
      result += String.fromCharCode(newCharCode);
    } else { // Non-alphabetic characters
      result += char;
    }
  }

  return result;
};

