function isNonNegativeInteger(value) {
  if (typeof value !== 'number') {
    return false;
  }
  if (!Number.isFinite(value)) {
    return false;
  }
  return Math.floor(value) === value && value >= 0;
}

function decimalToBinary(decimalNum) {
  if (!isNonNegativeInteger(decimalNum)) {
    throw new TypeError('decimalToBinary expects a non-negative integer');
  }
  if (decimalNum === 0) {
    return '0';
  }
  let remaining = decimalNum;
  let bits = '';
  while (remaining > 0) {
    const bit = remaining % 2;
    bits = (bit === 1 ? '1' : '0') + bits;
    remaining = (remaining - bit) / 2;
  }
  return bits;
}

function bitValue(character) {
  if (character === '0') {
    return 0;
  }
  if (character === '1') {
    return 1;
  }
  throw new RangeError(`invalid binary digit: ${character}`);
}

function binaryToDecimal(binaryStr) {
  if (typeof binaryStr !== 'string') {
    throw new TypeError('binaryToDecimal expects a string');
  }
  if (binaryStr.length === 0) {
    throw new TypeError('binaryToDecimal expects a non-empty string');
  }
  let total = 0;
  for (const character of binaryStr) {
    total = total * 2 + bitValue(character);
  }
  return total;
}

function padToWidth(binaryStr, width) {
  let padded = binaryStr;
  while (padded.length < width) {
    padded = '0' + padded;
  }
  return padded;
}

function parseDecimalInput(text) {
  const trimmed = String(text).trim();
  if (!/^\d+$/.test(trimmed)) {
    return null;
  }
  return Number(trimmed);
}

function describe(text) {
  const value = parseDecimalInput(text);
  if (value === null) {
    return `${text} -> not a valid non-negative integer`;
  }
  const bits = decimalToBinary(value);
  const status = binaryToDecimal(bits) === value ? 'ok' : 'mismatch';
  return `${value} -> ${padToWidth(bits, 8)} (${bits.length} bits, ${status})`;
}

function main() {
  const inputs = ['0', '2', '13', '255', '1024', ' 7 ', 'twelve'];
  for (const input of inputs) {
    console.log(describe(input));
  }
}

main();

