const simpleMovingAverage = (data, windowSize) => {
  if (windowSize === 0 || data.length < windowSize) {
    return [];
  }

  const result = [];
  let currentSum = 0;

  for (let i = 0; i < data.length; i++) {
    currentSum += data[i];

    if (i >= windowSize - 1) {
      result.push(currentSum / windowSize);
      currentSum -= data[i - (windowSize - 1)];
    }
  }

  return result;
};

