const majorityElement = (nums) => {
  let candidate = nums[0];
  let count = 0;

  for (let i = 0; i < nums.length; i++) {
    const num = nums[i]; 
    if (count === 0) {
      candidate = num;
      count = 1;
    } else if (num === candidate) {
      count++;
    } else {
      count--;
    }
  }

  // The problem statement guarantees a majority element always exists,
  // so no second pass is strictly necessary to verify.
  // We can just return the candidate.
  return candidate;
};

