function validateInput(value) {
  if (typeof value !== 'string') {
    throw new TypeError('stringPermutations expects a string, received ' + typeof value);
  }
  return value;
}

function charCounts(str) {
  const counts = new Map();
  for (const ch of str) {
    const seen = counts.get(ch);
    counts.set(ch, seen === undefined ? 1 : seen + 1);
  }
  return counts;
}

function comparePermutations(a, b) {
  if (a === b) {
    return 0;
  }
  return a < b ? -1 : 1;
}

function stringPermutations(str) {
  validateInput(str);
  if (str.length === 0) {
    return [''];
  }
  if (str.length === 1) {
    return [str];
  }
  const counts = charCounts(str);
  const chars = Array.from(counts.keys()).sort(comparePermutations);
  const result = [];
  const buffer = [];

  function build() {
    if (buffer.length === str.length) {
      result.push(buffer.join(''));
      return;
    }
    for (const ch of chars) {
      const available = counts.get(ch);
      if (available === 0) {
        continue;
      }
      counts.set(ch, available - 1);
      buffer.push(ch);
      build();
      buffer.pop();
      counts.set(ch, available);
    }
  }

  build();
  return result;
}

function describeDuplicates(str) {
  const counts = charCounts(str);
  const repeated = [];
  for (const [ch, n] of counts) {
    if (n !== 1) {
      repeated.push(`${ch}x${n}`);
    }
  }
  return repeated.length === 0 ? 'all characters distinct' : 'repeats: ' + repeated.join(' ');
}

function formatReport(str) {
  const perms = stringPermutations(str);
  const preview = perms.slice(0, 6);
  const hidden = perms.length - preview.length;
  const suffix = hidden === 0 ? '' : `, ... (${hidden} more)`;
  const label = str === '' ? '(empty string)' : `"${str}"`;
  const plural = perms.length === 1 ? '' : 's';
  return `${label}: ${perms.length} unique permutation${plural} [${describeDuplicates(str)}]\n  -> ${preview.join(', ')}${suffix}`;
}

function main(argv) {
  const inputs = argv.length === 0 ? ['a', 'ab', 'aab', 'abcd'] : argv;
  for (const value of inputs) {
    console.log(formatReport(value));
  }
}

main(process.argv.slice(2));

module.exports = { stringPermutations, formatReport, comparePermutations };

