function isPowerOfTwo(n) {
  if (typeof n !== 'number') {
    return false;
  }
  if (!Number.isInteger(n)) {
    return false;
  }
  if (n < 1) {
    return false;
  }
  return (n & (n - 1)) === 0;
}

function exponentOfTwo(n) {
  if (!isPowerOfTwo(n)) {
    return null;
  }
  let exponent = 0;
  let value = n;
  while (value !== 1) {
    value = value / 2;
    exponent += 1;
  }
  return exponent;
}

function parseInput(text) {
  const trimmed = String(text).trim();
  if (trimmed === '') {
    return null;
  }
  const value = Number(trimmed);
  if (Number.isNaN(value)) {
    return null;
  }
  return value;
}

function describe(text) {
  const value = parseInput(text);
  if (value === null) {
    return `"${text}" is not a valid integer`;
  }
  const exponent = exponentOfTwo(value);
  if (exponent === null) {
    return `${value} -> false`;
  }
  return `${value} -> true (2^${exponent})`;
}

function summarize(inputs) {
  let powers = 0;
  let others = 0;
  let invalid = 0;
  for (const item of inputs) {
    const value = parseInput(item);
    if (value === null) {
      invalid += 1;
    } else if (isPowerOfTwo(value)) {
      powers += 1;
    } else {
      others += 1;
    }
  }
  return { powers, others, invalid };
}

function main() {
  const inputs = ['1', '2', '3', '16', '0', '-8', '1024', '100', 'abc'];
  for (const item of inputs) {
    console.log(describe(item));
  }
  const stats = summarize(inputs);
  console.log(`powers of two: ${stats.powers}, other integers: ${stats.others}`);
  const label = stats.invalid === 1 ? 'entry' : 'entries';
  console.log(`unparsable ${label}: ${stats.invalid}`);
}

main();

