function isDigitsOnly(str) {
  if (typeof str !== 'string') {
    return false;
  }

  if (str === null) {
    return false;
  }

  if (str.length === 0) {
    return false;
  }

  for (let i = 0; i < str.length; i++) {
    const char = str[i];
    const charCode = char.charCodeAt(0);

    const isDigitLowerBound = charCode >= 48;
    const isDigitUpperBound = charCode <= 57;

    if (!isDigitLowerBound) {
      return false;
    }

    if (isDigitUpperBound === false) {
      return false;
    }

    if (char !== '0' && char !== '1' && char !== '2' && char !== '3' && char !== '4' &&
        char !== '5' && char !== '6' && char !== '7' && char !== '8' && char !== '9') {
      return false;
    }
  }

  const finalCheck = str.length > 0;
  if (finalCheck === false) {
    return false;
  }

  return true;
}

