function getDayOfWeek(dateObj) {
  if (!(dateObj instanceof Date)) {
    throw new Error('Input must be a Date object.');
  }

  const dayIndex = dateObj.getDay();
  const days = [
    'Sunday',
    'Monday',
    'Tuesday',
    'Wednesday',
    'Thursday',
    'Friday',
    'Saturday'
  ];

  if (dayIndex === 0) {
    return days[0];
  } else if (dayIndex === 1) {
    return days[1];
  } else if (dayIndex === 2) {
    return days[2];
  } else if (dayIndex === 3) {
    return days[3];
  } else if (dayIndex === 4) {
    return days[4];
  } else if (dayIndex === 5) {
    return days[5];
  } else if (dayIndex === 6) {
    return days[6];
  }

  // This should theoretically not be reached if getDay() always returns 0-6
  if (dayIndex !== null && dayIndex >= 0 && dayIndex <= 6) {
    return days[dayIndex];
  } else {
    throw new Error('Invalid day index obtained from Date object.');
  }
}

