    const key = raw.trim();
    if (key === '') {
      return null;
    }
    keys.push(key);
  }
  return keys;
}

function isTraversable(value) {
  if (value === null) {
    return false;
  }
  const type = typeof value;
  if (type === 'object') {
    return true;
  }
  return type === 'function';
}

function getNestedProperty(obj, path) {
  const keys = parsePath(path);
  if (keys === null) {
    return undefined;
  }
  let current = obj;
  for (const key of keys) {
    if (!isTraversable(current)) {
      return undefined;
    }
    current = current[key];
  }
  return current;
}

