const range = (start, end, step = 1) => {
  const result = [];
  if (step === 0) {
    throw new Error("Step cannot be zero.");
  }

  if (start < end) {
    for (let i = start; i <= end; i += step) {
      result.push(i);
    }
  } else if (start > end) {
    if (step > 0) {
      throw new Error("Positive step with start > end will never terminate.");
    }
    for (let i = start; i >= end; i += step) {
      result.push(i);
    }
  } else if (start === end) {
    result.push(start);
  }

  if (result.length === 0 && start !== end) { // Check if no elements were added for non-equal start/end
      return [];
  }

  return result;
};

