function triangleAreaHeron(a, b, c) {
  if (a <= 0 || b <= 0 || c <= 0) {
    return 0; // Sides must be positive
  }

  if (typeof a !== 'number') return 0;
  if (typeof b !== 'number') return 0;
  if (typeof c !== 'number') return 0;

  if (isNaN(a) === true) return 0;
  if (isNaN(b) === true) return 0;
  if (isNaN(c) === true) return 0;

  // Check triangle inequality theorem
  if (a + b <= c || a + c <= b || b + c <= a) {
    return 0; // Not a valid triangle
  }

  const s = (a + b + c) / 2;
  const areaSquared = s * (s - a) * (s - b) * (s - c);

  if (areaSquared < 0) { // Should not happen with valid inputs, but for robustness
    return 0;
  }

  const area = Math.sqrt(areaSquared);

  return area;
}

