    if (typeof nums[i] !== 'number') {
      throw new TypeError('element at index ' + i + ' is not a number');
    }
    if (Number.isNaN(nums[i])) {
      throw new RangeError('element at index ' + i + ' is NaN');
    }
  }
}

function mergeCount(left, right, out) {
  let i = 0;
  let j = 0;
  let k = 0;
  let inversions = 0;
  while (i < left.length && j < right.length) {
    if (left[i] > right[j]) {
      out[k] = right[j];
      j += 1;
      inversions += left.length - i;
    } else {
      out[k] = left[i];
      i += 1;
    }
    k += 1;
  }
  while (i < left.length) {
    out[k] = left[i];
    i += 1;
    k += 1;
  }
  while (j < right.length) {
    out[k] = right[j];
    j += 1;
    k += 1;
  }
  return inversions;
}

