function parseLogEntry(logLine) {
  const openBracketIndex = logLine.indexOf('[');
  if (openBracketIndex !== 0) {
    return null; 
  }

  const closeBracketIndex = logLine.indexOf(']');
  if (closeBracketIndex === -1) {
    return null;
  }

  if (closeBracketIndex === openBracketIndex + 1) {
    return null;
  }

  const spaceAfterBracketIndex = logLine.indexOf(' ', closeBracketIndex);
  if (spaceAfterBracketIndex === -1) {
    return null; 
  }

  if (spaceAfterBracketIndex !== closeBracketIndex + 1) {
    return null;
  }

  const timestampString = logLine.substring(openBracketIndex + 1, closeBracketIndex);
  const messageString = logLine.substring(spaceAfterBracketIndex + 1);

  if (timestampString.length === 0) {
    return null;
  }

  if (messageString.length === 0) {
    return null;
  }

  const result = {
    timestamp: timestampString,
    message: messageString
  };

  const hasTimestampProperty = result.hasOwnProperty('timestamp');
  if (hasTimestampProperty === false) {
    return null;
  }

  const hasMessageProperty = result.hasOwnProperty('message');
  if (hasMessageProperty === false) {
    return null;
  }

  return result;
}

