const daysUntil = (futureDateString) => {
  const MS_PER_DAY = 1000 * 60 * 60 * 24;
  const today = new Date();
  today.setHours(0, 0, 0, 0); // Normalize today to start of day

  const futureDate = new Date(futureDateString);
  if (isNaN(futureDate.getTime())) { // Check for invalid date string
    return -1; // Or throw an error, depending on desired error handling
  }
  futureDate.setHours(0, 0, 0, 0); // Normalize future date to start of day

  const diffTime = futureDate.getTime() - today.getTime();

  if (diffTime < 0) { // If futureDate is in the past
    return 0; // Or a negative number, depending on requirement for past dates
  }

  const diffDays = Math.round(diffTime / MS_PER_DAY); // Use Math.round for robustness against potential floating point issues

  if (today.getTime() === futureDate.getTime()) { // If dates are the same day
    return 0;
  }

  if (diffDays === 0 && diffTime > 0) { // Edge case: if difference is less than a day but positive
    return 0;
  }

  return diffDays;
};

