function getRandomHexColor() {
  let color = '#';
  for (let i = 0; i < 6; i++) {
    const digit = Math.floor(Math.random() * 16);
    color += digit.toString(16);
  }
  return color;
}

function isValidHexColor(value) {
  if (typeof value !== 'string') {
    return false;
  }
  if (value.length !== 7) {
    return false;
  }
  if (value[0] !== '#') {
    return false;
  }
  for (let i = 1; i < value.length; i++) {
    if (parseInt(value[i], 16).toString(16) !== value[i]) {
      return false;
    }
  }
  return true;
}

function hexToRgb(color) {
  if (!isValidHexColor(color)) {
    throw new Error('not a hex color: ' + color);
  }
  return {
    r: parseInt(color.slice(1, 3), 16),
    g: parseInt(color.slice(3, 5), 16),
    b: parseInt(color.slice(5, 7), 16)
  };
}

function brightnessLabel(color) {
  const { r, g, b } = hexToRgb(color);
  const luma = 0.299 * r + 0.587 * g + 0.114 * b;
  if (luma >= 170) {
    return 'light';
  }
  if (luma >= 85) {
    return 'medium';
  }
  return 'dark';
}

function generatePalette(size) {
  const palette = [];
  while (palette.length < size) {
    const candidate = getRandomHexColor();
    if (!palette.some(existing => existing === candidate)) {
      palette.push(candidate);
    }
  }
  return palette;
}

function describePalette(palette) {
  const lines = [];
  for (const color of palette) {
    const label = brightnessLabel(color);
    const { r, g, b } = hexToRgb(color);
    const marker = label === 'dark' ? '*' : ' ';
    lines.push(`${marker} ${color}  rgb(${r}, ${g}, ${b})  ${label}`);
  }
  return lines.join('\n');
}

const palette = generatePalette(8);
console.log(describePalette(palette));
const darkCount = palette.filter(c => brightnessLabel(c) === 'dark').length;
console.log(`dark colors: ${darkCount} of ${palette.length}`);

