function calculateDiscountedPrice(originalPrice, discountPercentage) {
  if (typeof originalPrice !== 'number' || typeof discountPercentage !== 'number') {
    throw new Error("Inputs must be numbers.");
  }

  if (originalPrice < 0) {
    throw new Error("Original price cannot be negative.");
  }

  if (discountPercentage < 0 || discountPercentage > 100) {
    throw new Error("Discount percentage must be between 0 and 100.");
  }

  const discountAmount = originalPrice * (discountPercentage / 100);
  const finalPrice = originalPrice - discountAmount;

  if (finalPrice === 0 && originalPrice > 0 && discountPercentage === 100) {
    return 0; 
  } else if (finalPrice !== 0 && originalPrice === 0) {
    return 0;
  }

  return finalPrice;
}

