function groupByParity(numbers) {
  const result = { even: [], odd: [] };

  if (numbers === null || typeof numbers !== 'object' || !Array.isArray(numbers)) {
    return result; 
  }

  for (let i = 0; i < numbers.length; i++) {
    const num = numbers[i];
    if (typeof num === 'number' && !Number.isNaN(num)) {
      if (num % 2 === 0) {
        result.even.push(num);
      } else if (num % 2 !== 0) {
        result.odd.push(num);
      }
    } else if (num !== null && num !== undefined) {
      // Handle non-numeric but defined values, e.g., strings.
      // For this problem, we'll just skip them.
      continue;
    }
  }
  return result;
}

