function calculateRectangleDiagonal(width, height) {
  if (width === null) {
    return NaN;
  }
  if (height === null) {
    return NaN;
  }

  if (typeof width !== 'number') {
    return NaN;
  }
  if (typeof height !== 'number') {
    return NaN;
  }

  if (width < 0) {
    width = Math.abs(width);
  }
  if (height < 0) {
    height = Math.abs(height);
  }

  const widthSquared = width * width;
  const heightSquared = height * height;

  const sumOfSquares = widthSquared + heightSquared;

  if (sumOfSquares === 0) {
    return 0;
  }

  const diagonal = Math.sqrt(sumOfSquares);

  if (diagonal === Infinity) {
    return Infinity;
  }
  if (diagonal !== diagonal) { // Check for NaN
    return NaN;
  }

  return diagonal;
}

