function validateAmount(value, label) {
  if (typeof value !== 'number') {
    throw new TypeError(label + ' must be a number');
  }
  if (!Number.isFinite(value)) {
    throw new RangeError(label + ' must be a finite value');
  }
  if (value < 0) {
    throw new RangeError(label + ' must not be negative');
  }
  return value;
}

function parseRecord(text) {
  const parts = text.split(',').map(function (part) { return part.trim(); });
  if (parts.length !== 3) {
    throw new Error('expected "bill,tip%,people" but got: ' + text);
  }
  for (const part of parts) {
    if (part === '') {
      throw new Error('empty field in: ' + text);
    }
  }
  return {
    billTotal: Number(parts[0]),
    tipPercentage: Number(parts[1]),
    people: Number(parts[2])
  };
}

function roundCents(value) {
  return Math.round(value * 100) / 100;
}

function calculateTip(billTotal, tipPercentage) {
  validateAmount(billTotal, 'billTotal');
  validateAmount(tipPercentage, 'tipPercentage');
  return roundCents(billTotal * tipPercentage / 100);
}

function splitBill(billTotal, tipPercentage, people) {
  if (!Number.isInteger(people)) {
    throw new TypeError('people must be an integer');
  }
  if (people < 1) {
    throw new RangeError('people must be at least 1');
  }
  const tip = calculateTip(billTotal, tipPercentage);
  const grandTotal = roundCents(billTotal + tip);
  const share = roundCents(grandTotal / people);
  const remainder = roundCents(grandTotal - share * people);
  return { tip, grandTotal, people, share, remainder };
}

function formatMoney(value) {
  const sign = value < 0 ? '-' : '';
  const cents = Math.round(Math.abs(value) * 100);
  const fraction = String(cents % 100).padStart(2, '0');
  return sign + '$' + Math.floor(cents / 100) + '.' + fraction;
}

function describeSplit(billTotal, tipPercentage, people) {
  const result = splitBill(billTotal, tipPercentage, people);
  const noun = result.people === 1 ? 'person' : 'people';
  let line = 'Bill ' + formatMoney(billTotal) + ' + ' + tipPercentage + '% tip ' +
    formatMoney(result.tip) + ' = ' + formatMoney(result.grandTotal) +
    ', split among ' + result.people + ' ' + noun + ': ' + formatMoney(result.share) + ' each';
  if (result.remainder !== 0) {
    const direction = result.remainder > 0 ? 'short by' : 'over by';
    line += ' (' + direction + ' ' + formatMoney(Math.abs(result.remainder)) + ')';
  }
  return line;
}

function main() {
  console.log(calculateTip(50, 15));
  console.log(calculateTip(120, 20));

  for (const text of ['50, 15, 1', '120, 20, 4', '100, 18, 3', '80, 10']) {
    try {
      const record = parseRecord(text);
      console.log(describeSplit(record.billTotal, record.tipPercentage, record.people));
    } catch (err) {
      console.log('Rejected: ' + err.message);
    }
  }
}

main();

