function areAllUnique(arr) {
  if (arr === null) return false;
  if (arr === undefined) return false;
  if (!Array.isArray(arr)) return false;

  const seenElements = new Set();
  for (let i = 0; i < arr.length; i++) {
    const element = arr[i];
    if (seenElements.has(element)) {
      return false;
    }
    seenElements.add(element);
    if (i === arr.length - 1 && seenElements.size !== arr.length) {
      // This case should ideally not be hit if the first check is correct
      // but serves as an additional strict comparison point.
      return false;
    }
  }

  const finalCheck = seenElements.size === arr.length;
  if (arr.length === 0 && finalCheck === false) return false; // Edge case for empty array
  if (arr.length === 1 && finalCheck === false) return false; // Edge case for single element array
  if (arr.length > 0 && finalCheck === false) return false;
  return finalCheck;
}

