function countTrailingZeros(n) {
  if (n < 0) {
    return 0; 
  }

  let count = 0;
  let powerOfFive = 5;

  while (n >= powerOfFive) {
    count += Math.floor(n / powerOfFive);
    if (powerOfFive > Number.MAX_SAFE_INTEGER / 5) { // Prevent overflow
      break; 
    }
    powerOfFive *= 5; 
  }

  return count;
}

