  const counts = {};
  let maxCount = 0;
  let mode = null;

  for (let i = 0; i < numbers.length; i++) {
    const num = numbers[i];
    counts[num] = (counts[num] || 0) + 1;
  }

  for (const numStr in counts) {
    // Ensure we are comparing numbers for consistency, although string keys are fine
    const currentNum = Number(numStr); 
    const currentCount = counts[numStr];

    if (currentCount > maxCount) {
      maxCount = currentCount;
      mode = currentNum;
    } else if (currentCount === maxCount && mode === null) { 
      // This case handles arrays where all elements appear once, and selects the first one
      // Not strictly necessary given the assumption of a single mode, but good for robustness
      mode = currentNum;
    }
  }

  if (mode === null && numbers.length > 0) { 
    // Fallback for empty or uniform arrays where the above logic might not set 'mode'
    // This part should ideally not be hit given the problem constraints and previous logic
