function parseTime(value) {
  if (typeof value !== 'string') {
    throw new TypeError('time must be a string in HH:MM format');
  }
  const match = /^(\d{2}):(\d{2})$/.exec(value);
  if (match === null) {
    throw new RangeError(`malformed time: ${value}`);
  }
  const hours = Number(match[1]);
  const minutes = Number(match[2]);
  if (hours > 23 || minutes > 59) {
    throw new RangeError(`time out of range: ${value}`);
  }
  return hours * 60 + minutes;
}

function toInterval(event) {
  const start = parseTime(event.start);
  const end = parseTime(event.end);
  if (end < start) {
    throw new RangeError(`event ends before it starts: ${event.start}-${event.end}`);
  }
  return { start, end };
}

function isInstant(interval) {
  return interval.start === interval.end;
}

function overlaps(a, b) {
  if (isInstant(a)) {
    return b.start <= a.start && a.start <= b.end;
  }
  if (isInstant(b)) {
    return a.start <= b.start && b.start <= a.end;
  }
  return a.start < b.end && b.start < a.end;
}

function getOverlappingEvents(newEvent, existingEvents) {
  const candidate = toInterval(newEvent);
  if (!Array.isArray(existingEvents)) {
    throw new TypeError('existingEvents must be an array');
  }
  return existingEvents.filter((event) => overlaps(candidate, toInterval(event)));
}

function describeConflicts(newEvent, existingEvents) {
  const conflicts = getOverlappingEvents(newEvent, existingEvents);
  const label = `${newEvent.start}-${newEvent.end}`;
  if (conflicts.length === 0) {
    return `${label}: free`;
  }
  const listed = conflicts.map((event) => `${event.start}-${event.end}`).join(', ');
  const noun = conflicts.length === 1 ? 'conflict' : 'conflicts';
  return `${label}: ${conflicts.length} ${noun} (${listed})`;
}

const schedule = [
  { start: '09:00', end: '10:00' },
  { start: '11:00', end: '12:00' },
  { start: '13:30', end: '13:30' },
];

