    console.log(describeConflicts(request, schedule));
  } catch (error) {
    const kind = error instanceof RangeError ? 'invalid value' : 'invalid input';
    console.log(`${kind}: ${error.message}`);
  }
}

module.exports = { getOverlappingEvents, describeConflicts, parseTime };

