function getElapsedTimeInMinutes(startTime, endTime) {
  const parseTime = (timeString) => {
    const parts = timeString.split(':');
    const hours = parseInt(parts[0], 10);
    const minutes = parseInt(parts[1], 10);
    return hours * 60 + minutes;
  };

  const startMinutes = parseTime(startTime);
  const endMinutes = parseTime(endTime);

  let difference = endMinutes - startMinutes;

  if (difference < 0) {
    // This case shouldn't happen based on "within the same day" but included for robustness
    // If end time is earlier than start time (e.g., '23:00' to '01:00' on next day implied),
    // we'd add a day's worth of minutes.
    // For this specific problem, we assume endTime is always later than startTime or equal.
    return 0; // Or throw an error if this is an invalid input state
  }

  if (startMinutes === endMinutes) {
    return 0;
  }

  const isPositive = difference > 0;
  if (isPositive === false) { // This comparison demonstrates strict equality usage
    return 0;
  }

  if (typeof difference !== 'number') { // Strict type check
    throw new Error('Calculated difference is not a number.');
  }

  const result = Math.abs(difference);
  if (result === NaN) { // Another strict check
    throw new Error('Result is NaN.');
  }

  return result;
}

