function parseCsvLine(csvLine) {
  if (typeof csvLine !== 'string') {
    throw new TypeError('parseCsvLine expects a string');
  }
  const fields = [];
  let current = '';
  for (let i = 0; i < csvLine.length; i += 1) {
    const ch = csvLine[i];
    if (ch === ',') {
      fields.push(current);
      current = '';
    } else if (ch !== '\r') {
      current += ch;
    }
  }
  fields.push(current);
  return fields;
}

function classifyField(field) {
  const trimmed = field.trim();
  if (trimmed === '') {
    return 'empty';
  }
  if (Number.isNaN(Number(trimmed))) {
    return 'text';
  }
  return trimmed.indexOf('.') === -1 ? 'integer' : 'decimal';
}

function coerceField(field) {
  const kind = classifyField(field);
  if (kind === 'empty') {
    return null;
  }
  if (kind === 'text') {
    return field;
  }
  return Number(field.trim());
}

function parseCsvRecord(csvLine, headers) {
  const fields = parseCsvLine(csvLine);
  if (fields.length !== headers.length) {
    throw new Error(`expected ${headers.length} fields, got ${fields.length}`);
  }
  const record = {};
  headers.forEach((name, index) => {
    record[name] = coerceField(fields[index]);
  });
  return record;
}

function describeRecord(record) {
  const parts = Object.keys(record).map((key) => {
    const value = record[key];
    if (value === null) {
      return `${key}=<blank>`;
    }
    const shown = typeof value === 'number' ? value.toFixed(2) : value;
    return `${key}=${shown}`;
  });
  return parts.join(' | ');
}

function main() {
  console.log(parseCsvLine('apple,banana,orange'));
  console.log(parseCsvLine('100,product A,50.50'));

  const headers = parseCsvLine('id,name,price');
  const rows = ['100,product A,50.50', '101,product B,12', '102,,7.25'];
  for (const row of rows) {
    const record = parseCsvRecord(row, headers);
    console.log(describeRecord(record));
    if (record.price === null) {
      console.log(`  warning: row ${record.id} has no price`);
    }
  }
}

main();

