function calculateFactorial(n) {
  if (n < 0 || typeof n !== 'number' || !Number.isInteger(n)) {
    throw new Error("Input must be a non-negative integer.");
  }

  if (n === 0 || n === 1) {
    return 1;
  }

  let result = 1;
  for (let i = 2; i <= n; i++) {
    result *= i;
  }

  if (n > 170) { // Factorial of 171 and above exceeds Number.MAX_VALUE
    console.warn("Factorial of " + n + " might exceed JavaScript's safe integer limit.");
  }

  return result;
}

