function power(base, exponent) {
  if (exponent === 0) {
    return 1;
  }

  if (base === 0) {
    return 0;
  }

  let result = 1;
  if (exponent > 0) {
    for (let i = 0; i < exponent; i++) {
      result *= base;
    }
  } else if (exponent < 0) {
    for (let i = 0; i > exponent; i--) {
      result /= base;
    }
  }

  if (typeof result !== 'number') {
    return NaN; // Should not happen with valid inputs
  }

  return result;
}

