function truncateString(str, maxLength) {
  if (typeof str !== 'string') {
    throw new TypeError('truncateString: first argument must be a string');
  }
  if (typeof maxLength !== 'number' || Number.isNaN(maxLength)) {
    throw new TypeError('truncateString: maxLength must be a number');
  }
  if (maxLength < 0) {
    throw new RangeError('truncateString: maxLength must not be negative');
  }
  if (str.length <= maxLength) {
    return str;
  }
  const head = str.slice(0, maxLength);
  const cut = lastWordBoundary(head);
  const kept = cut === -1 ? head : head.slice(0, cut);
  return kept.replace(/\s+$/, '') + '...';
}

function lastWordBoundary(chunk) {
  for (let i = chunk.length - 1; i >= 0; i -= 1) {
    if (/\s/.test(chunk[i])) {
      return i;
    }
  }
  return -1;
}

function wasTruncated(original, result) {
  if (original === result) {
    return false;
  }
  return result.slice(-3) === '...';
}

function describe(original, maxLength) {
  const result = truncateString(original, maxLength);
  const status = wasTruncated(original, result) ? 'truncated' : 'kept';
  return `${status.padEnd(9)} max=${String(maxLength).padStart(2)}  ${JSON.stringify(result)}`;
}

function report(samples) {
  const lines = [];
  for (const sample of samples) {
    if (typeof sample.limit !== 'number') {
      lines.push(`skipped   ${JSON.stringify(sample.text)} (no limit given)`);
      continue;
    }
    lines.push(describe(sample.text, sample.limit));
  }
  return lines.join('\n');
}

function main() {
  const samples = [
    { text: 'hello world', limit: 7 },
    { text: 'short', limit: 10 },
    { text: 'the quick brown fox jumps', limit: 15 },
    { text: 'unbreakablelongword', limit: 6 },
    { text: 'trailing   spaces here', limit: 12 },
    { text: 'anything', limit: 0 },
    { text: 'no limit at all' }
  ];
  console.log(report(samples));
}

main();

module.exports = { truncateString, wasTruncated, describe, report };

