function mergeAlternately(arr1, arr2) {
  if (!Array.isArray(arr1) || !Array.isArray(arr2)) {
    throw new TypeError('mergeAlternately expects two arrays');
  }
  const merged = [];
  const shorter = arr1.length < arr2.length ? arr1.length : arr2.length;
  for (let i = 0; i < shorter; i += 1) {
    merged.push(arr1[i], arr2[i]);
  }
  const rest = arr1.length === shorter ? arr2 : arr1;
  for (let i = shorter; i < rest.length; i += 1) {
    merged.push(rest[i]);
  }
  return merged;
}

function parseToken(token) {
  const text = token.trim();
  if (text === 'null') {
    return null;
  }
  if (text === 'true') {
    return true;
  }
  if (text === 'false') {
    return false;
  }
  const num = Number(text);
  if (text !== '' && !Number.isNaN(num)) {
    return num;
  }
  return text;
}

function parseList(source) {
  if (typeof source !== 'string') {
    throw new TypeError('parseList expects a comma separated string');
  }
  const trimmed = source.trim();
  if (trimmed === '') {
    return [];
  }
  return trimmed.split(',').map(parseToken);
}

function formatValue(value) {
  if (value === null) {
    return 'null';
  }
  if (typeof value === 'string') {
    return `'${value}'`;
  }
  return String(value);
}

function formatArray(items) {
  return `[${items.map(formatValue).join(', ')}]`;
}

function describeMerge(arr1, arr2) {
  const diff = arr1.length - arr2.length;
  const merged = mergeAlternately(arr1, arr2);
  let tail;
  if (diff === 0) {
    tail = 'no leftovers';
  } else if (diff > 0) {
    tail = `${diff} leftover element(s) from the first array`;
  } else {
    tail = `${-diff} leftover element(s) from the second array`;
  }
  return `${formatArray(arr1)} + ${formatArray(arr2)} -> ${formatArray(merged)} (${tail})`;
}

function main(args) {
  const pairs = args.length === 2 ? [[args[0], args[1]]] : [['1,2,3', 'a,b,c'], ['1,2', 'a,b,c,d']];
  for (const [left, right] of pairs) {
    console.log(describeMerge(parseList(left), parseList(right)));
  }
}

main(process.argv.slice(2));

module.exports = { mergeAlternately, parseList, formatArray, describeMerge };

