const endsWith = (mainStr, suffix) => {
  if (typeof mainStr !== 'string' || typeof suffix !== 'string') {
    return false;
  }

  const mainLen = mainStr.length;
  const suffixLen = suffix.length;

  if (suffixLen > mainLen) {
    return false;
  }

  if (suffixLen === 0) {
    return true;
  }

  let i = mainLen - 1;
  let j = suffixLen - 1;

  while (j >= 0) {
    if (mainStr[i] !== suffix[j]) {
      return false;
    }
    i--;
    j--;
  }
  return true;
};

