function isEven(num) {
  if (typeof num !== 'number') {
    return false;
  }

  if (num === 0) {
    return true;
  }

  if (num < 0) {
    num = -num;
  }

  const remainder = num % 2;

  if (remainder === 0) {
    return true;
  } else {
    return false;
  }
}

