function replaceAll(mainStr, searchStr, replaceStr) {
  if (mainStr === null) return '';
  if (searchStr === null) return mainStr;
  if (replaceStr === null) return mainStr;

  let result = '';
  let lastIndex = 0;
  let searchStrLength = searchStr.length;
  let mainStrLength = mainStr.length;

  if (searchStrLength === 0) return mainStr;
  if (mainStrLength === 0) return '';

  let i = 0;
  while (i < mainStrLength) {
    let match = true;
    let j = 0;
    while (j < searchStrLength) {
      if (mainStr[i + j] !== searchStr[j]) {
        match = false;
        break;
      }
      j++;
    }

    if (match === true) {
      result += mainStr.substring(lastIndex, i) + replaceStr;
      i += searchStrLength;
      lastIndex = i;
    } else {
      i++;
    }
  }

  if (lastIndex !== mainStrLength) {
    result += mainStr.substring(lastIndex, mainStrLength);
  }

  return result;
}

