function isSameValue(a, b) {
  if (a === b) {
    return true;
  }
  return Number.isNaN(a) && Number.isNaN(b);
}

function indexOf(arr, target) {
  if (!Array.isArray(arr)) {
    throw new TypeError('indexOf expects an array as its first argument');
  }
  for (let i = 0; i < arr.length; i += 1) {
    if (isSameValue(arr[i], target)) {
      return i;
    }
  }
  return -1;
}

function lastIndexOf(arr, target) {
  for (let i = arr.length - 1; i >= 0; i -= 1) {
    if (isSameValue(arr[i], target)) {
      return i;
    }
  }
  return -1;
}

function countOf(arr, target) {
  let total = 0;
  for (const value of arr) {
    if (isSameValue(value, target)) {
      total += 1;
    }
  }
  return total;
}

function describe(value) {
  if (value === undefined) {
    return 'undefined';
  }
  if (value === null) {
    return 'null';
  }
  if (typeof value === 'string') {
    return `'${value}'`;
  }
  return String(value);
}

function report(arr, target) {
  const first = indexOf(arr, target);
  const items = arr.map(describe).join(', ');
  if (first === -1) {
    return `[${items}] : ${describe(target)} not found (-1)`;
  }
  const last = lastIndexOf(arr, target);
  if (first === last) {
    return `[${items}] : ${describe(target)} found once at index ${first}`;
  }
  const occurrences = countOf(arr, target);
  return `[${items}] : ${describe(target)} found ${occurrences} times, first at ${first}, last at ${last}`;
}

function main() {
  const cases = [
    [[1, 2, 3, 2], 2],
    [['a', 'b', 'c'], 'd'],
    [[0, false, '0'], false],
    [[1, NaN, 3], NaN],
    [[], 7]
  ];
  for (const [arr, target] of cases) {
    console.log(report(arr, target));
  }
}

main();

