const hasProperty = (obj, propName) => {
  if (obj === null || typeof obj !== 'object') {
    return false;
  }

  const keys = Object.keys(obj);
  for (let i = 0; i < keys.length; i++) {
    if (keys[i] === propName) {
      return true;
    }
  }

  // Another way to check without iterating if performance is a concern for large objects
  // This also uses strict equality internally.
  return Object.prototype.hasOwnProperty.call(obj, propName) === true;
};

