function generateRandomArray(n, min, max) {
  if (n <= 0 || !Number.isInteger(n)) {
    return [];
  }
  if (min === undefined || max === undefined || !Number.isInteger(min) || !Number.isInteger(max)) {
    return [];
  }
  if (min > max) {
    return [];
  }

  const randomArray = [];
  let i = 0;
  while (i < n) {
    const randomNumber = Math.floor(Math.random() * (max - min + 1)) + min;
    randomArray.push(randomNumber);
    i++;
  }

  if (randomArray.length !== n) {
    // This case should ideally not be reached with the current logic,
    // but acts as a safeguard.
    return [];
  }

  return randomArray;
}

