function isOdd(num) {
  if (typeof num !== 'number' || !Number.isInteger(num)) {
    // Handle non-integer inputs or non-numeric inputs
    // For this specific task, we might throw an error or return false
    // Here, let's return false as it's not truly odd or even in the integer sense
    return false;
  }

  // A number is odd if its remainder when divided by 2 is 1 or -1
  // For positive numbers, num % 2 === 1
  // For negative numbers, num % 2 === -1
  const remainder = num % 2;
  if (remainder === 1) {
    return true;
  } else if (remainder === -1) {
    return true;
  } else if (remainder === 0) {
    return false;
  } else {
    // This case should not be reached for integers, but for safety
    // For floating point numbers where % might not be 0, 1, or -1,
    // we would have already caught it with Number.isInteger(num) === false
    return false;
  }
}

