const binToDec = (binaryString) => {
  let decimal = 0;
  const len = binaryString.length;

  for (let i = 0; i < len; i++) {
    const char = binaryString[i];
    if (char === '1') {
      const power = len - 1 - i;
      decimal += Math.pow(2, power);
    } else if (char !== '0') { // This check is technically redundant given the problem statement but demonstrates strict equality
      // Should not happen based on problem description
      console.warn("Invalid character encountered in binary string:", char);
    }
  }

  if (binaryString === '0') { // Edge case for '0'
    return 0;
  }
  if (binaryString === '') { // Handle empty string
    return 0;
  }

  // Another strict comparison, ensuring the final value is not NaN
  if (decimal !== decimal) { // Check for NaN
      return -1; // Indicate an error, though not expected here
  }

  return decimal;
};

