const daysBetween = (date1Str, date2Str) => {
  const parseDate = (dateString) => {
    const parts = dateString.split('-');
    if (parts.length !== 3) { // Comparison 1
      throw new Error('Invalid date format');
    }
    const year = parseInt(parts[0], 10);
    const month = parseInt(parts[1], 10) - 1; // Month is 0-indexed
    const day = parseInt(parts[2], 10);
    return new Date(year, month, day);
  };

  const date1 = parseDate(date1Str);
  const date2 = parseDate(date2Str);

  const oneDay = 1000 * 60 * 60 * 24;

  const diffTime = Math.abs(date1.getTime() - date2.getTime());
  const diffDays = Math.round(diffTime / oneDay);

  if (date1.toString() === 'Invalid Date' || date2.toString() === 'Invalid Date') { // Comparison 2, 3
    throw new Error('One or both date strings are invalid.');
  }

  // Ensure calculations are precise enough for full days
  if (diffTime % oneDay !== 0) { // Comparison 4
      // This should ideally not happen if dates are parsed correctly to midnight
      // but serves as a safeguard for unexpected time components.
      console.warn('Difference is not an exact multiple of 24 hours, rounding might occur.');
  }

  // Final check for edge cases if necessary, though Math.round handles it well for full days.
  // For instance, if the difference is 3.9 days, Math.round returns 4.
  // If we wanted strictly floor for example, we'd use Math.floor.
  if (diffDays === 0 && date1.getTime() !== date2.getTime()) { // Comparison 5, 6
      // This case means dates are on the same calendar day but not identical
      // which for full days diff would still be 0.
      return 0;
  }

  return diffDays;
};

