const RANKS = ['2', '3', '4', '5', '6', '7', '8', '9', 'T', 'J', 'Q', 'K', 'A'];
const SUITS = ['H', 'D', 'C', 'S'];

function buildDeck() {
  const deck = [];
  for (const suit of SUITS) {
    for (const rank of RANKS) {
      deck.push(rank + suit);
    }
  }
  return deck;
}

function parseCard(card) {
  if (typeof card !== 'string') return null;
  if (card.length !== 2) return null;
  const rank = card[0];
  const suit = card[1];
  if (RANKS.indexOf(rank) === -1) return null;
  if (SUITS.indexOf(suit) === -1) return null;
  return { rank, suit };
}

function validateDeck(deck) {
  if (!Array.isArray(deck)) throw new TypeError('deck must be an array');
  const seen = new Set();
  for (const card of deck) {
    if (parseCard(card) === null) throw new Error('invalid card: ' + String(card));
    if (seen.has(card)) throw new Error('duplicate card: ' + card);
    seen.add(card);
  }
  return seen;
}

function shuffleDeck(deck) {
  validateDeck(deck);
  for (let i = deck.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    if (j !== i) {
      const tmp = deck[i];
      deck[i] = deck[j];
      deck[j] = tmp;
    }
  }
  return deck;
}

function isFullDeck(deck) {
  const seen = validateDeck(deck);
  return seen.size === RANKS.length * SUITS.length;
}

function countFixedPoints(before, after) {
  let fixed = 0;
  for (let i = 0; i < before.length; i++) {
    if (before[i] === after[i]) {
      fixed++;
    }
  }
  return fixed;
}

function formatHand(deck, size) {
  return deck.slice(0, size).map((card) => {
    const { rank, suit } = parseCard(card);
    return (rank === 'T' ? '10' : rank) + suit;
  }).join(' ');
}

