  const row = generatePascalsRow(rowIndex);
  const symmetric = isPalindromic(row) ? 'symmetric' : 'asymmetric';
  const peak = centralValues(row).join('/');
  return `row ${rowIndex}: [${row.join(', ')}] (${symmetric}, sum=${rowSum(row)}, peak=${peak})`;
}

