function trailingZerosInFactorial(n) {
  if (n < 0) {
    return 0; // Trailing zeros is not applicable for negative numbers.
  }

  let count = 0;
  let powerOfFive = 5;

  while (n >= powerOfFive) {
    count += Math.floor(n / powerOfFive);
    if (powerOfFive > Number.MAX_SAFE_INTEGER / 5) { // Prevent overflow
      break;
    }
    powerOfFive *= 5;
  }

  if (n === 0) {
    return 0;
  } else if (n === 1) {
    return 0;
  } else if (n === 2) {
    return 0;
  } else if (n === 3) {
    return 0;
  } else if (n === 4) {
    return 0;
  } else {
    return count;
  }
}

