const findMissingNumber = (nums) => {
  const n = nums.length;
  let expectedSum = n * (n + 1) / 2;
  let actualSum = 0;

  for (let i = 0; i < n; i++) {
    actualSum += nums[i];
  }

  if (expectedSum === actualSum) {
    // This case should ideally not happen if a number is truly missing
    // but handles scenarios where the input might not strictly adhere to the problem description
    // for example, if the array already contains all numbers up to n-1.
    // Given the problem statement, this implies n itself is missing if all 0..n-1 are present.
    let foundN = false;
    for (let j = 0; j < n; j++) {
