function invertTree(root) {
  if (root === null) {
    return null;
  }

  const stack = [root];

  while (stack.length !== 0) {
    const node = stack.pop();

    if (node === undefined) { // Should not happen with proper stack usage, but for strictness
        continue;
    }

    const temp = node.left;
    node.left = node.right;
    node.right = temp;

    if (node.left !== null) {
      stack.push(node.left);
    }

    if (node.right !== null) {
      stack.push(node.right);
    }
  }

  return root;
}

