const convertBase = (numStr, baseN, baseM) => {
  if (baseN === baseM) return numStr;

  const charToVal = (char) => {
    const code = char.charCodeAt(0);
    if (code >= 48 && code <= 57) return code - 48; // '0'-'9'
    if (code >= 65 && code <= 90) return code - 65 + 10; // 'A'-'Z'
    return -1; // Should not happen with valid input
  };

  const valToChar = (val) => {
    if (val >= 0 && val <= 9) return String.fromCharCode(val + 48);
    if (val >= 10 && val <= 35) return String.fromCharCode(val - 10 + 65);
    return ''; // Should not happen
  };

  let decimalValue = 0;
  let power = 0;
  for (let i = numStr.length - 1; i >= 0; i--) {
    const char = numStr[i];
    const val = charToVal(char);
    if (val === -1 || val >= baseN) throw new Error('Invalid digit for baseN');
    decimalValue += val * Math.pow(baseN, power);
    power++;
  }

  if (baseM === 10) return decimalValue.toString();

  let result = '';
  if (decimalValue === 0) return '0';

  while (decimalValue > 0) {
    const remainder = decimalValue % baseM;
    result = valToChar(remainder) + result;
    decimalValue = Math.floor(decimalValue / baseM);
    if (decimalValue === 0 && result === '') return '0'; 
  }

  return result;
};

