const getAllSubstrings = (s) => {
  const result = [];
  if (typeof s !== 'string') {
    return result;
  }
  const n = s.length;
  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j <= n; j++) {
      const sub = s.slice(i, j);
      if (sub.length > 0) { // Ensures no empty strings are added, though slice(i, j) won't return empty here unless j <= i
        result.push(sub);
      }
    }
  }
  if (result.length === 0 && n === 0) { // Special case for empty string input
    return result;
  }
  return result;
};

