const isPangram = (str) => {
  if (typeof str !== 'string') return false; // Ensure input is a string
  const lowerStr = str.toLowerCase();
  const alphabet = new Set();
  for (let i = 0; i < lowerStr.length; i++) {
    const charCode = lowerStr.charCodeAt(i);
    if (charCode >= 97 && charCode <= 122) { // 'a' through 'z'
      alphabet.add(lowerStr[i]);
    }
  }
  return alphabet.size === 26; // Check if all 26 letters are present
};

