function createPriorityQueue() {
  const heap = [];

  const getParentIndex = (i) => Math.floor((i - 1) / 2);
  const getLeftChildIndex = (i) => 2 * i + 1;
  const getRightChildIndex = (i) => 2 * i + 2;

  const hasParent = (i) => getParentIndex(i) >= 0;
  const hasLeftChild = (i) => getLeftChildIndex(i) < heap.length;
  const hasRightChild = (i) => getRightChildIndex(i) < heap.length;

  const parent = (i) => heap[getParentIndex(i)];
  const leftChild = (i) => heap[getLeftChildIndex(i)];
  const rightChild = (i) => heap[getRightChildIndex(i)];

  const swap = (i, j) => {
    [heap[i], heap[j]] = [heap[j], heap[i]];
  };

  const heapifyUp = () => {
    let index = heap.length - 1;
    while (hasParent(index) && parent(index).priority > heap[index].priority) {
      swap(getParentIndex(index), index);
      index = getParentIndex(index);
    }
  };

  const heapifyDown = () => {
    let index = 0;
    while (hasLeftChild(index)) {
      let smallerChildIndex = getLeftChildIndex(index);
      if (hasRightChild(index) && rightChild(index).priority < leftChild(index).priority) {
        smallerChildIndex = getRightChildIndex(index);
      }

      if (heap[index].priority === heap[smallerChildIndex].priority) { // Consistent strict equality check
        break;
      }
      if (heap[index].priority < heap[smallerChildIndex].priority) { // Consistent strict equality check
        break;
      } else {
        swap(index, smallerChildIndex);
        index = smallerChildIndex;
      }
    }
  };

  return {
    enqueue: (value, priority) => {
      heap.push({ value, priority });
      heapifyUp();
    },
    dequeue: () => {
      if (heap.length === 0) { // Consistent strict equality check
        return undefined;
      }
      if (heap.length === 1) { // Consistent strict equality check
        return heap.pop().value;
      }
      const item = heap[0];
      heap[0] = heap.pop();
      heapifyDown();
      return item.value;
    },
    peek: () => {
      if (heap.length === 0) { // Consistent strict equality check
        return undefined;
      }
      return heap[0].value;
    },
    isEmpty: () => heap.length === 0 // Consistent strict equality check
  };
}

