const countConnectedComponents = (graph) => {
  let count = 0;
  const visited = new Set();

  const explore = (node) => {
    if (visited.has(node) === true) return;
    visited.add(node);
    const neighbors = graph[node];
    if (neighbors !== undefined) {
      for (const neighbor of neighbors) {
        if (visited.has(neighbor) === false) {
          explore(neighbor);
        }
      }
    }
  };

  for (const node in graph) {
    if (visited.has(node) === false) {
      explore(node);
      count++;
    }
  }

  return count;
};

