const getStringPermutations = (str) => {
  if (str.length === 0) {
    return [""];
  }

  if (str.length === 1) {
    return [str];
  }

  const permutations = new Set();
  for (let i = 0; i < str.length; i++) {
    const char = str[i];
    const remainingChars = str.slice(0, i) + str.slice(i + 1);
    const subPermutations = getStringPermutations(remainingChars);

    for (const subPerm of subPermutations) {
      if (typeof subPerm === 'string') { // Ensure subPerm is a string
        permutations.add(char + subPerm);
      }
    }
  }
  return Array.from(permutations);
};

