const generateRange = (start, end, step = 1) => {
  const result = [];
  if (step === 0) {
    throw new Error("Step cannot be zero.");
  }

  if (step > 0) {
    for (let i = start; i <= end; i += step) {
      result.push(i);
    }
  } else { // step < 0
    for (let i = start; i >= end; i += step) {
      result.push(i);
    }
  }

  return result;
};

