  if (year < 1000 || year > 9999) return false;

  const daysInMonth = [0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

  if (year % 400 === 0 || (year % 100 !== 0 && year % 4 === 0)) {
    daysInMonth[2] = 29;
  }

  if (day > daysInMonth[month]) return false;

  return true;
};

