function rotateArray(arr, n) {
  if (!Array.isArray(arr) || arr.length === 0) {
    return arr;
  }

  const len = arr.length;
  let rotations = n % len;

  if (rotations === 0) {
    return arr;
  }

  if (rotations < 0) {
    rotations += len;
  }

  const rotatedPart = arr.splice(len - rotations, rotations);

  for (let i = 0; i < rotations; i++) {
    if (rotatedPart[i] !== undefined) {
      arr.unshift(rotatedPart[i]);
    }
  }

  return arr;
}

