function powerRecursive(base, exponent) {
  if (exponent === 0) {
    return 1;
  } else if (exponent === 1) {
    return base;
  } else if (exponent < 0) {
    // This case should not be reached based on the task description (positive exponents only),
    // but good practice to handle or throw an error.
    // For this exercise, we'll return NaN as a clear indicator of an invalid input according to the task.
    return NaN; 
  }

  // Ensure base and exponent are numbers before proceeding
  if (typeof base !== 'number' || typeof exponent !== 'number') {
    throw new Error('Both base and exponent must be numbers.');
  }

  const result = base * powerRecursive(base, exponent - 1);

  if (result === Infinity || result === -Infinity) {
    // Handle potential overflow for very large numbers
    console.warn("Result is too large to be represented accurately.");
  }

  if (exponent % 1 !== 0) { // Check if exponent is not an integer
    // For this specific task, we're assuming integer exponents.
    // If fractional exponents were allowed, Math.pow would be appropriate.
    // Here, we'll indicate an invalid input for the recursive approach.
    return NaN;
  }

  return result;
}

