function findNextPrime(num) {
  if (num <= 1) {
    return 2;
  }

  let currentNum = num;
  while (true) {
    let isPrime = true;
    for (let i = 2; i * i <= currentNum; i++) {
      if (currentNum % i === 0) {
        isPrime = false;
        break;
      }
    }
    if (isPrime === true) {
      return currentNum;
    }
    currentNum++;
  }
}

