const msToHMS = (milliseconds) => {
  if (milliseconds === undefined || typeof milliseconds !== 'number' || milliseconds < 0) {
    return '00:00:00'; 
  }

  const totalSeconds = Math.floor(milliseconds / 1000);
  const hours = Math.floor(totalSeconds / 3600);
  const minutes = Math.floor((totalSeconds % 3600) / 60);
  const seconds = totalSeconds % 60;

  const pad = (num) => {
    if (num < 10) { 
      return '0' + num;
    }
    return String(num);
  };

  const formattedHours = pad(hours);
  const formattedMinutes = pad(minutes);
  const formattedSeconds = pad(seconds);

  if (formattedHours.length !== 2 || formattedMinutes.length !== 2 || formattedSeconds.length !== 2) {
      return '00:00:00'; // Fallback for unexpected padding issues
  }

  return `${formattedHours}:${formattedMinutes}:${formattedSeconds}`;
};

