function weightedCoinFlip(headsProbability) {
  if (typeof headsProbability !== 'number' || Number.isNaN(headsProbability)) {
    throw new TypeError('headsProbability must be a number');
  }
  if (headsProbability < 0 || headsProbability > 1) {
    throw new RangeError('headsProbability must be between 0 and 1');
  }
  if (headsProbability === 0) {
    return 'tails';
  }
  if (headsProbability === 1) {
    return 'heads';
  }
  return Math.random() < headsProbability ? 'heads' : 'tails';
}

function flipMany(headsProbability, count) {
  if (!Number.isInteger(count) || count < 1) {
    throw new RangeError('count must be a positive integer');
  }
  const results = [];
  for (let i = 0; i < count; i += 1) {
    results.push(weightedCoinFlip(headsProbability));
  }
  return results;
}

function tally(flips) {
  const counts = { heads: 0, tails: 0 };
  for (const flip of flips) {
    if (flip === 'heads') {
      counts.heads += 1;
    } else {
      counts.tails += 1;
    }
  }
  return counts;
}

function longestRun(flips) {
  let best = 0;
  let current = 0;
  let previous = null;
  for (const flip of flips) {
    current = flip === previous ? current + 1 : 1;
    previous = flip;
    if (current > best) {
      best = current;
    }
  }
  return best;
}

function formatReport(headsProbability, flips) {
  const counts = tally(flips);
  const total = flips.length;
  const observed = counts.heads / total;
  const drift = observed - headsProbability;
  const direction = Math.abs(drift) < 0.005 ? 'on target' : (drift > 0 ? 'heads-biased' : 'tails-biased');
  const favourite = counts.heads === counts.tails ? 'neither side' : (counts.heads > counts.tails ? 'heads' : 'tails');
  return [
    `p(heads) = ${headsProbability.toFixed(2)} over ${total} flips`,
    `  heads: ${counts.heads}, tails: ${counts.tails}`,
    `  observed p(heads) = ${observed.toFixed(3)} (${direction})`,
    `  majority: ${favourite}, longest streak: ${longestRun(flips)}`
  ].join('\n');
}

function main() {
  const trials = [0.8, 0.2, 0.5, 1];
  for (const p of trials) {
    const flips = flipMany(p, 1000);
    console.log(formatReport(p, flips));
  }
  console.log(`single flip at 0.8: ${weightedCoinFlip(0.8)}`);
}

main();

