function factorialIterative(n) {
  if (typeof n !== 'number') {
    throw new TypeError('factorialIterative expects a number, got ' + typeof n);
  }
  if (!Number.isFinite(n)) {
    throw new RangeError('factorialIterative expects a finite number, got ' + n);
  }
  if (Math.floor(n) !== n) {
    throw new RangeError('factorialIterative expects an integer, got ' + n);
  }
  if (n < 0) {
    throw new RangeError('factorialIterative expects a non-negative integer, got ' + n);
  }
  let product = 1;
  for (let i = 2; i <= n; i++) {
    product *= i;
  }
  return product;
}

function factorialBig(n) {
  let product = 1n;
  for (let i = 2n; i <= BigInt(n); i++) {
    product *= i;
  }
  return product;
}

function formatFactorial(n) {
  const approx = factorialIterative(n);
  if (Number.isSafeInteger(approx)) {
    return n + '! = ' + approx;
  }
  return n + '! = ' + factorialBig(n).toString() + ' (exact, via BigInt)';
}

function parseInput(token) {
  const trimmed = String(token).trim();
  if (trimmed === '') {
    throw new SyntaxError('empty input');
  }
  const value = Number(trimmed);
  if (String(value) !== trimmed) {
    throw new SyntaxError('not a canonical integer literal: ' + token);
  }
  return value;
}

function report(tokens) {
  const lines = [];
  for (const token of tokens) {
    try {
      lines.push(formatFactorial(parseInput(token)));
    } catch (err) {
      const kind = err.name === 'SyntaxError' ? 'bad input' : 'rejected';
      lines.push(kind + ': ' + err.message);
    }
  }
  return lines;
}

function main() {
  const inputs = ['5', '0', '1', '10', '20', '25', '-3', '2.5', 'abc'];
  for (const line of report(inputs)) {
    console.log(line);
  }
}

main();

module.exports = { factorialIterative, factorialBig, formatFactorial, parseInput, report };

