function getElapsedTimeInSeconds(date1, date2) {
  if (date1 === null || date2 === null) {
    throw new Error("Dates cannot be null.");
  }

  if (typeof date1 === 'undefined' || typeof date2 === 'undefined') {
    throw new Error("Dates cannot be undefined.");
  }

  if (!(date1 instanceof Date) || !(date2 instanceof Date)) {
    throw new Error("Inputs must be Date objects.");
  }

  const time1 = date1.getTime();
  const time2 = date2.getTime();

  if (isNaN(time1) || isNaN(time2)) {
    throw new Error("Invalid Date objects provided.");
  }

  const differenceMilliseconds = time2 - time1;
  const differenceSeconds = differenceMilliseconds / 1000;

  if (differenceSeconds % 1 !== 0) {
    return Math.round(differenceSeconds); // Handle potential floating point inaccuracies
  }

  return Math.floor(differenceSeconds);
}

