function isPlainRecord(item) {
  if (item === null) {
    return false;
  }
  return typeof item === 'object';
}

function filterObjectsByKey(arr, key, value) {
  if (!Array.isArray(arr)) {
    throw new TypeError('filterObjectsByKey: arr must be an array');
  }
  if (typeof key !== 'string') {
    throw new TypeError('filterObjectsByKey: key must be a string');
  }
  if (key.length === 0) {
    throw new TypeError('filterObjectsByKey: key must not be empty');
  }
  const result = [];
  for (const item of arr) {
    if (!isPlainRecord(item)) {
      continue;
    }
    if (!Object.prototype.hasOwnProperty.call(item, key)) {
      continue;
    }
    if (item[key] === value) {
      result.push(item);
    }
  }
  return result;
}

function groupByKey(arr, key) {
  const groups = new Map();
  for (const item of arr) {
    if (!isPlainRecord(item)) {
      continue;
    }
    const raw = item[key];
    const label = raw === undefined ? '(missing)' : String(raw);
    if (!groups.has(label)) {
      groups.set(label, []);
    }
    groups.get(label).push(item);
  }
  return groups;
}

function distinctValues(arr, key) {
  const seen = [];
  for (const item of arr) {
    if (!isPlainRecord(item)) {
      continue;
    }
    if (!seen.some((v) => v === item[key])) {
      seen.push(item[key]);
    }
  }
  return seen;
}

function describeMatches(arr, key, value) {
  const matches = filterObjectsByKey(arr, key, value);
  if (matches.length === 0) {
    return `no object matches ${key} of ${JSON.stringify(value)}`;
  }
  const ids = matches.map((m) => (m.id === undefined ? '?' : m.id));
  const noun = matches.length === 1 ? 'object' : 'objects';
  return `${matches.length} ${noun} with ${key} = ${JSON.stringify(value)}: ids ${ids.join(', ')}`;
}

const records = [
  { id: 1, type: 'A', active: true },
  { id: 2, type: 'B', active: false },
  { id: 3, type: 'A', active: true },
  { id: 4, active: true },
  null,
  { id: 5, type: 'A', active: false }
];

console.log(filterObjectsByKey([{ id: 1, type: 'A' }, { id: 2, type: 'B' }], 'type', 'A'));
console.log(filterObjectsByKey([{ id: 1, type: 'A' }], 'type', 'C'));
console.log(describeMatches(records, 'type', 'A'));
console.log(describeMatches(records, 'type', 'Z'));
console.log(describeMatches(records, 'active', false));

for (const [label, members] of groupByKey(records, 'type')) {
  const status = label === '(missing)' ? 'untyped' : `type ${label}`;
  console.log(`${status}: ${members.length} record(s)`);
}

console.log('distinct types:', distinctValues(records, 'type').map((v) => (v === undefined ? 'undefined' : v)).join(' | '));

