function isValidEmail(email) {
  if (typeof email !== 'string') {
    return false;
  }
  const trimmed = email.trim();
  if (trimmed.length === 0) {
    return false;
  }
  const at = trimmed.indexOf('@');
  if (at === -1) {
    return false;
  }
  if (trimmed.lastIndexOf('@') !== at) {
    return false;
  }
  const dot = trimmed.indexOf('.', at);
  if (dot === -1) {
    return false;
  }
  return at > 0 && dot > at + 1 && dot < trimmed.length - 1;
}

function splitEmail(email) {
  if (!isValidEmail(email)) {
    return null;
  }
  const trimmed = email.trim();
  const at = trimmed.indexOf('@');
  return { local: trimmed.slice(0, at), domain: trimmed.slice(at + 1) };
}

function explain(email) {
  if (typeof email !== 'string') {
    return 'not a string';
  }
  const trimmed = email.trim();
  if (trimmed === '') {
    return 'empty string';
  }
  const at = trimmed.indexOf('@');
  if (at === -1) {
    return "missing '@'";
  }
