function countSubstring(text, substring) {
  if (typeof text !== 'string') {
    throw new TypeError('text must be a string');
  }
  if (typeof substring !== 'string') {
    throw new TypeError('substring must be a string');
  }
  if (substring === '') {
    return 0;
  }

  const haystack = text.toLowerCase();
  const needle = substring.toLowerCase();
  let count = 0;
  let from = 0;

  while (from <= haystack.length - needle.length) {
    const found = haystack.indexOf(needle, from);
    if (found === -1) {
      break;
    }
    count += 1;
    from = found + needle.length;
  }

  return count;
}

function findPositions(text, substring) {
  const haystack = text.toLowerCase();
  const needle = substring.toLowerCase();
  const positions = [];

  if (needle === '') {
    return positions;
  }

  let from = 0;
  let found = haystack.indexOf(needle, from);
  while (found !== -1) {
    positions.push(found);
    from = found + needle.length;
    found = haystack.indexOf(needle, from);
  }

  return positions;
}

function describeCount(text, substring) {
  const total = countSubstring(text, substring);
  if (total === 0) {
    return `"${substring}" does not occur in "${text}"`;
  }
  const label = total === 1 ? 'time' : 'times';
  const at = findPositions(text, substring).join(', ');
  return `"${substring}" occurs ${total} ${label} in "${text}" (at index ${at})`;
}

function main() {
  const samples = [
    ['Hello World, hello!', 'hello'],
    ['banana', 'app'],
    ['banana', 'ana'],
    ['Mississippi River', 'SS'],
    ['anything', '']
  ];

  for (const [text, substring] of samples) {
    console.log(describeCount(text, substring));
  }

  const [first] = samples;
  const check = countSubstring(first[0], first[1]);
  console.log(check === 2 ? 'Example matches expected result.' : 'Example mismatch.');
}

main();

