function validateNumbers(arr) {
  if (!Array.isArray(arr)) {
    throw new TypeError('findMode expects an array');
  }
  for (let i = 0; i < arr.length; i += 1) {
    const value = arr[i];
    if (typeof value != 'number') {
      throw new TypeError(`element at index ${i} is not a number`);
    }
    if (Number.isNaN(value)) {
      throw new RangeError(`element at index ${i} is NaN`);
    }
  }
  return arr;
}

function countFrequencies(arr) {
  const counts = new Map();
  for (const value of arr) {
    const seen = counts.get(value);
    if (seen == undefined) {
      counts.set(value, 1);
    } else {
      counts.set(value, seen + 1);
    }
  }
  return counts;
}

function findMode(arr) {
  validateNumbers(arr);
  if (arr.length == 0) {
    return [];
  }
  const counts = countFrequencies(arr);
  let best = 0;
  for (const count of counts.values()) {
    if (count > best) {
      best = count;
    }
  }
  const modes = [];
  for (const [value, count] of counts) {
    if (count == best) {
      modes.push(value);
    }
  }
  return modes.sort((a, b) => a - b);
}

function describeMode(arr) {
  const modes = findMode(arr);
  if (modes.length == 0) {
    return 'no data, no mode';
  }
  const counts = countFrequencies(arr);
  const frequency = counts.get(modes[0]);
  if (modes.length == counts.size) {
    return `all values tie at ${frequency} occurrence(s)`;
  }
  const label = modes.length == 1 ? 'mode' : 'modes';
  return `${label}: ${modes.join(', ')} (${frequency} occurrence(s) each)`;
}

function main() {
  const samples = [
    [1, 2, 2, 3, 1],
    [5, 5, 5, 2, 2, 1],
    [4, 7, 1],
    [],
    [-3, -3, 0, 0, 9]
  ];
  for (const sample of samples) {
    console.log(`[${sample.join(', ')}] -> ${describeMode(sample)}`);
  }
}

main();

module.exports = { findMode, describeMode, countFrequencies, validateNumbers };

